const $ = (id) => document.getElementById(id);
const canvas = $('preview');
let ctx = canvas.getContext('2d');
// NOTE: `ctx` is `let`, not `const` — paintStickerSamples() and
// paintTweetSamples() temporarily swap it to a card's small canvas so
// the previews are painted with the real style code (restored in a
// finally).
const statusEl = $('status');
const textInput = $('textInput');
let toastTimer = null;

// Dismissible "tap to type" hint: the × hides it and remembers the
// choice, so it stays gone on later opens.
const hintPill = $('hintPill');
const hintClose = $('hintClose');
try {
  if (localStorage.getItem('fontstory:hintDismissed') === '1') hintPill?.classList.add('hidden');
} catch { /* private mode */ }
hintClose?.addEventListener('click', (e) => {
  e.stopPropagation();
  hintPill?.classList.add('hidden');
  try { localStorage.setItem('fontstory:hintDismissed', '1'); } catch { /* private mode */ }
});

function setStatus(msg, sticky) {
  if (!msg) { statusEl.hidden = true; return; }
  statusEl.textContent = msg;
  statusEl.hidden = false;
  clearTimeout(toastTimer);
  // Sticky toasts (e.g. "sending…") stay up until the next status
  // replaces them, so a slow request never looks like it vanished.
  if (!sticky) toastTimer = setTimeout(() => { statusEl.hidden = true; }, 2600);
}
function inTelegram() { return typeof Telegram !== 'undefined' && Telegram.WebApp; }

function callEndpoint(name, input) {
  return new Promise((resolve, reject) => {
    if (!inTelegram() || !Telegram.WebApp.Serverless) {
      reject(new Error('خارج از تلگرام باز شده — ذخیره و کارهای اخیر فقط داخل تلگرام کار می‌کنه.'));
      return;
    }
    Telegram.WebApp.Serverless.call(name, input || {}, (err, result) => {
      if (err) reject(new Error(err.message || 'خطا در تماس با سرور'));
      else resolve(result);
    });
  });
}

// --- Canvas rendering (transparent background; PNG export has no bg) ---
function fontFamily() {
  const f = FONTS.find((x) => x.id === state.font) || importedFonts.get(state.font);
  return f ? f.family : "'Vazirmatn', sans-serif";
}

function isRTLText(text) {
  // Persian/Arabic/Hebrew ranges — the app is Persian-first.
  return /[\u0590-\u05FF\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]/.test(text);
}

function spaceWidth() {
  return ctx.measureText(' ').width;
}

// Full width of one line, including letter + word spacing.
function lineWidth(line) {
  const words = line.split(' ').filter((w) => w !== '');
  if (!words.length) return 0;
  let total = words.reduce((sum, w) => sum + ctx.measureText(w).width, 0);
  total += (words.length - 1) * (spaceWidth() + state.wordSpacing);
  return total;
}

// Text colour that stays readable on a given background: dark text on
// light backgrounds, white text on dark ones.
function contrastText(hex) {
  const m = /^#([0-9a-fA-F]{6})$/.exec(hex || '');
  if (!m) return '#FFFFFF';
  const r = parseInt(m[1].slice(0, 2), 16);
  const g = parseInt(m[1].slice(2, 4), 16);
  const b = parseInt(m[1].slice(4, 6), 16);
  return (0.299 * r + 0.587 * g + 0.114 * b) > 150 ? '#1F2421' : '#FFFFFF';
}

// '#RRGGBB' + opacity -> 'rgba(r,g,b,a)'.
function hexAlpha(hex, alpha) {
  const m = /^#([0-9a-fA-F]{6})$/.exec(hex || '');
  if (!m) return `rgba(255,255,255,${alpha})`;
  const r = parseInt(m[1].slice(0, 2), 16);
  const g = parseInt(m[1].slice(2, 4), 16);
  const b = parseInt(m[1].slice(4, 6), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}

function wrapLines(text, maxWidth) {
  return wrapLineRanges(text, maxWidth).map((r) => r.text);
}

// Same wrapping as wrapLines, but each line also carries its character
// range [start, end] in the original text — the canvas-drawn selection
// highlight needs to know which characters each line holds. Keep the
// wrapping loop identical to wrapLines so the ranges never drift.
// \n is a hard break: wrap each paragraph on its own and keep empty
// lines, so Enter in the editor really moves to the next line.
function wrapLineRanges(text, maxWidth) {
  const ranges = [];
  let paraStart = 0;
  for (const para of text.split('\n')) {
    const words = [...para.matchAll(/\S+/g)].map((m) => ({ w: m[0], i: m.index }));
    if (!words.length) { ranges.push({ text: '', start: paraStart, end: paraStart }); paraStart += para.length + 1; continue; }
    let line = '';
    let lineStart = -1; // offset of the line's first word in the original text
    let lineEnd = -1;   // offset just past the line's last word
    for (const { w, i } of words) {
      const test = line ? line + ' ' + w : w;
      if (lineWidth(test) > maxWidth && line) {
        ranges.push({ text: line, start: lineStart, end: lineEnd });
        line = w; lineStart = paraStart + i; lineEnd = paraStart + i + w.length;
      } else {
        if (!line) lineStart = paraStart + i;
        line = test; lineEnd = paraStart + i + w.length;
      }
    }
    if (line) ranges.push({ text: line, start: lineStart, end: lineEnd });
    paraStart += para.length + 1;
  }
  return ranges.length ? ranges : [{ text: '', start: 0, end: 0 }];
}

// Width of the first n characters of a line, measured the same way the
// line is drawn (word by word, with the word gaps). Used to place the
// canvas-drawn selection highlight. extraGap is the justify stretch
// for this line (0 unless the line is justified — see justifyGap).
function prefixWidth(line, n, extraGap = 0) {
  n = Math.max(0, Math.min(n, line.length));
  if (n === 0) return 0;
  const words = line.split(' ').filter((w) => w !== '');
  const gap = spaceWidth() + state.wordSpacing + extraGap;
  let x = 0, off = 0;
  for (const w of words) {
    if (n <= off) return x;
    if (n <= off + w.length) {
      const k = n - off;
      // The boundary after k chars of a word sits one letter-spacing
      // past the measured k-char prefix (the spacing before the next
      // char), except at the word's edges.
      const extra = (k > 0 && k < w.length && 'letterSpacing' in ctx) ? state.letterSpacing : 0;
      return x + ctx.measureText(w.slice(0, k)).width + extra;
    }
    x += ctx.measureText(w).width + gap;
    off += w.length + 1;
  }
  return x;
}

// Draw one line word by word (word spacing has no canvas API, so the
// words are positioned manually). RTL text runs right-to-left.
function drawWords(line, cx, y, dx = 0, dy = 0, mode = 'fill', textFill = true) {
  const words = line.split(' ').filter((w) => w !== '');
  if (!words.length) return;
  const lw = lineWidth(line);
  const rtl = isRTLText(line);
  const gap = spaceWidth() + state.wordSpacing + lineJustifyGap;
  // A justified line is wider than its natural width: the extra gap
  // per word gap stretches it to the block's full width.
  const visW = lw + lineJustifyGap * (words.length - 1);
  // A gradient text colour paints each line with the full gradient
  // across that line's glyph box. Only in fill mode, and only for
  // styles whose text fill is the text colour — 'gradient' and
  // 'sticker' paint their own fill and ignore the text colour.
  // `textFill` is false for calls that paint a SHADOW layer in a fixed
  // colour (pastille's extrusion): the gradient must not leak into it.
  if (mode === 'fill' && textFill && !['gradient', 'sticker'].includes(state.style) && isGradientColor(state.color)) {
    ctx.fillStyle = textColorFill(line, cx, y, visW);
  }
  let x = rtl ? cx + visW / 2 : cx - visW / 2;
  ctx.textAlign = rtl ? 'right' : 'left';
  for (const word of words) {
    if (mode === 'stroke') ctx.strokeText(word, x + dx, y + dy);
    else ctx.fillText(word, x + dx, y + dy);
    const ww = ctx.measureText(word).width;
    x += rtl ? -(ww + gap) : (ww + gap);
  }
  ctx.textAlign = 'center';
}

function roundRect(x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

// --- Style painting ---
// Each paint function draws ONE line of text at (cx, y) with that style's
// look. `lw` is the line's full width (incl. spacing), `fs` the font size.
function bgBox(cx, y, lw, fs, { fill, stroke, strokeWidth = 0, radius = 18, padX = 28, padY = 0 }) {
  const h = fs * 1.24 + padY;
  const w = lw + padX * 2;
  const r = Math.min(radius, h / 2, w / 2);
  ctx.save();
  roundRect(cx - w / 2, y - h / 2, w, h, r);
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = strokeWidth; ctx.stroke(); }
  ctx.restore();
}

function textGradient(cx, lw, stops) {
  const g = ctx.createLinearGradient(cx - lw / 2, 0, cx + lw / 2, 0);
  stops.forEach(([at, color]) => g.addColorStop(at, color));
  return g;
}

// The fill for a line of text: a plain colour, or a gradient colour
// spanning the line's glyph box at the recorded angle (gradient text
// colours, Reza 2026-11-21).
function textColorFill(line, cx, y, visW) {
  if (!isGradientColor(state.color)) return state.color;
  const g = parseGradientColor(state.color);
  if (!g) return state.color;
  const m = ctx.measureText(line);
  const x0 = cx - visW / 2, x1 = cx + visW / 2;
  const yTop = y - (m.actualBoundingBoxAscent || 0);
  const yBot = y + (m.actualBoundingBoxDescent || 0);
  let sx, sy, ex, ey;
  switch (g.angle) {
    case 0: sx = cx; sy = yBot; ex = cx; ey = yTop; break;
    case 90: sx = x0; sy = y; ex = x1; ey = y; break;
    case 180: sx = cx; sy = yTop; ex = cx; ey = yBot; break;
    case 270: sx = x1; sy = y; ex = x0; ey = y; break;
    case 45: sx = x0; sy = yBot; ex = x1; ey = yTop; break;
    case 135: sx = x0; sy = yTop; ex = x1; ey = yBot; break;
    case 225: sx = x1; sy = yTop; ex = x0; ey = yBot; break;
    case 315: sx = x1; sy = yBot; ex = x0; ey = yTop; break;
    default: sx = x0; sy = y; ex = x1; ey = y;
  }
  const grad = ctx.createLinearGradient(sx, sy, ex, ey);
  grad.addColorStop(0, g.c1);
  grad.addColorStop(1, g.c2);
  return grad;
}

function strokeWords(line, cx, y, color, width, dx = 0, dy = 0) {
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.lineJoin = 'round';
  drawWords(line, cx, y, dx, dy, 'stroke');
  ctx.restore();
}

// The quotes style's single-quote glyph (Reza 2026-11-23 — his
// createQuoteFrameStyle code, verbatim). One curved comma-like mark in
// a ~34x50 box; the frame draws it as a pair (two side by side) at the
// top gap and the same pair rotated 180° at the bottom gap.
const QUOTE_PATH =
  'M 26.5 4.2 C 28.5 2.8, 31.2 4.4, 30.0 6.8 ' +
  'C 26.8 13.0, 22.8 17.5, 20.5 23.2 ' +
  'C 26.2 24.4, 30.2 29.6, 29.8 35.8 ' +
  'C 29.3 43.2, 23.0 48.8, 15.5 48.4 ' +
  'C 7.5 48.0, 1.8 41.2, 2.2 32.5 ' +
  'C 2.8 20.2, 11.2 10.2, 26.5 4.2 Z';

const STYLE_PAINT = {
  bold: (line, cx, y) => { ctx.fillStyle = state.color; drawWords(line, cx, y); },
  highlight: (line, cx, y, lw, fs) => {
    bgBox(cx, y, lw, fs, { fill: state.styleColor, radius: state.borderRadius, padX: 24 });
    // Text colour: the رنگ tab's colour once the user picks one, else
    // auto-contrast against the box so the default stays readable.
    ctx.fillStyle = state.colorTouched ? state.color : contrastText(state.styleColor); drawWords(line, cx, y);
  },
  neon: (line, cx, y) => {
    ctx.shadowColor = flatColor(state.color); ctx.shadowBlur = sp('neonGlow'); ctx.fillStyle = state.color;
    drawWords(line, cx, y); ctx.shadowBlur = 0; drawWords(line, cx, y);
  },
  glow: (line, cx, y) => {
    ctx.shadowColor = flatColor(state.color); ctx.shadowBlur = sp('glowGlow'); ctx.fillStyle = state.color;
    drawWords(line, cx, y); ctx.shadowBlur = 0; drawWords(line, cx, y);
  },
  glass: (line, cx, y) => { ctx.fillStyle = state.color; drawWords(line, cx, y); },
  retro: (line, cx, y) => {
    const v = sp('retroOffset');
    ctx.fillStyle = '#FF2E88'; drawWords(line, cx, y, v, v);
    ctx.fillStyle = '#22D3EE'; drawWords(line, cx, y, -0.6 * v, -0.6 * v);
    ctx.fillStyle = state.color; drawWords(line, cx, y);
  },
  shadow: (line, cx, y) => {
    ctx.shadowColor = 'rgba(0,0,0,0.6)'; ctx.shadowBlur = sp('shadowBlur'); ctx.shadowOffsetY = sp('shadowOffset');
    ctx.fillStyle = state.color; drawWords(line, cx, y);
  },
  gradient: (line, cx, y, lw) => {
    ctx.fillStyle = textGradient(cx, lw, [[0, sp('gradientC1')], [1, sp('gradientC2')]]);
    drawWords(line, cx, y);
  },
  stroke: (line, cx, y, lw, fs) => {
    strokeWords(line, cx, y, '#111111', fs * (sp('strokeWidth') / 100));
    ctx.fillStyle = state.color; drawWords(line, cx, y);
  },
  brush: (line, cx, y, lw, fs) => {
    ctx.save(); ctx.translate(cx, y); ctx.rotate((sp('brushTilt') * Math.PI) / 180);
    ctx.fillStyle = sp('brushBoxC');
    roundRect(-lw / 2 - 30, -fs * 0.62, lw + 60, fs * 1.24, sp('brushBoxR')); ctx.fill(); ctx.restore();
    ctx.fillStyle = state.colorTouched ? state.color : contrastText(sp('brushBoxC')); drawWords(line, cx, y);
  },
  pastille: (line, cx, y, lw, fs) => {
    // Purple 3D (Reza 2026-11-23 — his createPurple3DTextStyle code,
    // replacing the flat purple outline): yellow text, a purple
    // outline, a dark-purple 3D extrusion swept down (and slightly
    // left) in 20 steps. His geometry, as % of fs (his font is 115px):
    // outline stroke 25%, shadow stroke 28.5%, extrusion dy 18% /
    // dx -2% (so dx = -dy/9). Each shadow layer is stroked AND filled
    // in the shadow colour (his SVG layers carry both fill and stroke,
    // paintOrder stroke fill); the outline is stroked AND filled in
    // the outline colour. The text follows the رنگ tab (solid or
    // gradient) once the user picks a colour, else his yellow #fff01f;
    // the layer copies pass textFill=false so a gradient text colour
    // can never leak into them.
    const dy = fs * (sp('pastilleShadow') / 100);
    const dx = -(1 / 9) * dy;
    const shadow = sp('pastilleShadowC');
    const sw = fs * 0.285;
    for (let i = 20; i >= 0; i--) {
      const t = i / 20;
      strokeWords(line, cx, y, shadow, sw, dx * t, dy * t);
      ctx.fillStyle = shadow;
      drawWords(line, cx, y, dx * t, dy * t, 'fill', false);
    }
    const outline = sp('pastilleOutlineC');
    strokeWords(line, cx, y, outline, fs * (sp('pastilleOutline') / 100));
    ctx.fillStyle = outline;
    drawWords(line, cx, y, 0, 0, 'fill', false);
    if (state.colorTouched) ctx.fillStyle = textColorFill(line, cx, y, lw);
    else ctx.fillStyle = '#fff01f';
    drawWords(line, cx, y);
  },
  // ('round' was deleted at Reza's request, 2026-11-23.)
  arcadia: (line, cx, y, lw, fs) => {
    strokeWords(line, cx, y, '#ffffff', fs * 0.06);
    ctx.fillStyle = textGradient(cx, lw, [[0, sp('arcadiaC1')], [1, sp('arcadiaC2')]]);
    drawWords(line, cx, y);
  },
  underline: (line, cx, y, lw, fs) => {
    // Highlight bar (Reza 2026-11-23 — his createHighlightBarTextStyle
    // code, replacing the 2026-11-22 shelf bar): the text sits ON a
    // thick violet bar; a dark-purple copy of the text, clipped to the
    // bar and offset down (and slightly left), reads as a shadow inside
    // the bar; the bar itself carries a soft drop shadow. His geometry,
    // from the text's bbox (measured here with actualBoundingBoxAscent
    // / Descent): the bar runs 0.34x fs past the text on each side,
    // its top is 56% down the bbox, its bottom 0.15x fs below the bbox
    // bottom. The text is white by default and follows the رنگ tab once
    // the user picks a colour.
    const m = ctx.measureText(line);
    const a = m.actualBoundingBoxAscent || fs * 0.8;
    const d = m.actualBoundingBoxDescent || fs * 0.2;
    const bboxH = a + d;
    const barW = lw + fs * 0.68;
    const barTop = y + bboxH * 0.06;
    const barBottom = y + bboxH * 0.5 + fs * 0.15;
    const barH = Math.max(fs * 0.21, barBottom - barTop);
    const barX = cx - barW / 2;
    // The bar + its drop shadow (his feDropShadow: dy 11% of fs, blur
    // 8.5% of fs, #1a020e at 0.52).
    ctx.save();
    ctx.shadowColor = 'rgba(26, 2, 14, 0.52)';
    ctx.shadowBlur = fs * 0.085;
    ctx.shadowOffsetY = fs * 0.11;
    ctx.fillStyle = sp('underlineC');
    ctx.fillRect(barX, barTop, barW, barH);
    ctx.restore();
    // The shadow text, clipped to the bar and offset down-left
    // (his dx -1.5% / dy 13% of fs). textFill=false so a gradient text
    // colour can never leak into it.
    ctx.save();
    ctx.beginPath();
    ctx.rect(barX, barTop, barW, barH);
    ctx.clip();
    ctx.fillStyle = sp('underlineShadowC');
    drawWords(line, cx, y, -fs * 0.015, fs * 0.13, 'fill', false);
    ctx.restore();
    // The text on top (white by default).
    if (state.colorTouched) ctx.fillStyle = textColorFill(line, cx, y, lw);
    else ctx.fillStyle = '#ffffff';
    drawWords(line, cx, y);
  },
  pixel: (line, cx, y) => { ctx.fillStyle = state.color; drawWords(line, cx, y); },
  quotes: (line, cx, y) => { ctx.fillStyle = state.color; drawWords(line, cx, y); },
  // ('winter' and 'rosseta' were deleted at Reza's request, 2026-11-23.)
  sticker: (line, cx, y, lw, fs) => {
    // Sticker 3D (Reza 2026-11-23 — his createSticker3DTextStyle code,
    // replacing v5): golden text, a red outline, a maroon 3D extrusion
    // swept down-left in 18 steps, and a white sticker border wrapping
    // the whole silhouette. His filter's geometry, as % of fs (his font
    // is 57.6px on a phone): red outline dilate 3.5px -> stroke 12%
    // (the existing def), extrusion dx -16 / dy 22 -> dy 38%,
    // dx/dy -16/22, white dilate 5px -> a ~9% rim beyond the combined
    // shape. The white ring is stroked at every sweep step too, so it
    // wraps the swept silhouette uniformly (the v5 technique); the
    // maroon copies are ALSO stroked (at the red outline width) so the
    // extrusion carries the outline's shape — exactly like his filter
    // sweeping redAlpha, not just the bare text. The text follows the
    // رنگ tab (solid or gradient) once the user picks a colour, else
    // his gold #ffc224; the layer copies pass textFill=false so a
    // gradient text colour can never leak into them.
    const w = fs * (sp('stickerOutline') / 100);
    const ww = w * 2.5;
    const dy = fs * (sp('stickerShadow') / 100);
    const dx = -(16 / 22) * dy;
    const steps = Math.max(1, Math.min(24, Math.ceil(Math.hypot(dx, dy) / 3)));
    const white = sp('stickerC');
    const maroon = sp('stickerShadowC');
    const red = sp('stickerOutlineC');
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      strokeWords(line, cx, y, white, ww, dx * t, dy * t);
    }
    for (let i = 1; i <= steps; i++) {
      const t = i / steps;
      strokeWords(line, cx, y, maroon, w, dx * t, dy * t);
      ctx.fillStyle = maroon;
      drawWords(line, cx, y, dx * t, dy * t, 'fill', false);
    }
    strokeWords(line, cx, y, red, w);
    if (state.colorTouched) ctx.fillStyle = textColorFill(line, cx, y, lw);
    else ctx.fillStyle = '#ffc224';
    drawWords(line, cx, y);
  },
  // StoryFont styles (Reza, 2026-11-22) — colours sampled from his
  // screenshots. Each one's fill follows the رنگ tab once the user picks
  // a colour, else the signature colour from the reference.
  // ('roundline' was deleted at Reza's request, 2026-11-23.)
  // ('pastille3d' was deleted at Reza's request, 2026-11-23.)
  // Box styles: the box itself is painted block-level in draw() (like
  // glass/quotes); the paint functions below only paint the text.
  gradline: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#FFFFFF';
    drawWords(line, cx, y);
  },
  squarebox: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#FFFFFF';
    drawWords(line, cx, y);
  },
  lightbox: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#111111';
    drawWords(line, cx, y);
  },
  shadowline: (line, cx, y, lw, fs) => {
    // A tall white bar behind each line with a soft drop shadow;
    // purple text by default (the reference).
    ctx.save();
    ctx.shadowColor = 'rgba(0,0,0,0.35)'; ctx.shadowBlur = 12; ctx.shadowOffsetY = 4;
    bgBox(cx, y, lw, fs, { fill: sp('shadowlineC'), radius: sp('shadowlineR'), padX: 30, padY: fs * 0.6 });
    ctx.restore();
    ctx.fillStyle = state.colorTouched ? state.color : '#663AB6';
    drawWords(line, cx, y);
  },
  // Tweet card: the text itself is grey (the black card + header +
  // footer are painted block-level in draw(), like glass/quotes).
  tweet: (line, cx, y) => {
    // Grey by default (the mockup); a colour picked in the رنگ tab wins.
    ctx.fillStyle = state.colorTouched ? state.color : '#A1A1AA';
    drawWords(line, cx, y);
  },
  // Notes frame: dark grey text on the light-grey content area (the
  // card + gold header are painted block-level in draw()). A colour
  // picked in the رنگ tab wins; if the content colour is changed,
  // contrastText keeps the text readable on it.
  note: (line, cx, y) => {
    const c = sp('noteC') || '#E5E5EA';
    ctx.fillStyle = state.colorTouched ? state.color
      : c.toUpperCase() === '#E5E5EA' ? '#595355' : contrastText(c);
    drawWords(line, cx, y);
  },
  // Pinned note card (Reza, 2026-11-23 — his createPinnedNoteCard
  // code): bold black text on a white card with a realistic 3D red
  // pushpin at the top-right (the card + pin are painted block-level in
  // draw(), like the note/message cards). A colour picked in the رنگ tab
  // wins; otherwise the text is his #0a0a0a on the white card, and
  // contrastText keeps it readable if the card colour is changed.
  pin: (line, cx, y) => {
    const c = sp('pinCardC') || '#FFFFFF';
    ctx.fillStyle = state.colorTouched ? state.color
      : c.toUpperCase() === '#FFFFFF' ? '#0a0a0a' : contrastText(c);
    drawWords(line, cx, y);
  },
  // Music player card (Reza, 2026-11-23 — his createMusicPlayerCard
  // code): the title in white on the dark glass card (the card + the
  // player chrome are painted block-level in draw(), like the
  // note/message cards). A colour picked in the رنگ tab wins (a
  // gradient paints the title via drawWords); otherwise the text is
  // white on the dark card, and contrastText keeps it readable if the
  // card colour is changed to something light.
  music: (line, cx, y) => {
    const c = sp('musicCardC') || '#1a040d';
    ctx.fillStyle = state.colorTouched ? state.color : contrastText(c);
    drawWords(line, cx, y);
  },
  // Pink frame text card (Reza, 2026-11-23 — his createPinkFrameTextCard
  // code): black text with a thick pink outline on a white card with a
  // thick pink border (the border is painted block-level in draw()).
  // His two-layer trick, verbatim in canvas: fill the glyph in the
  // accent (so the counters stay pink), stroke it in the accent (the
  // outer half is the visible outline), then fill it in the text colour
  // on top. The outline width is a % of the font size (his 22px at a
  // 112px font ≈ 20%). A colour picked in the رنگ tab wins for the
  // text; otherwise contrastText keeps it readable on the card colour.
  frame: (line, cx, y, lw, fs) => {
    const accent = sp('frameAccent') || '#ff96aa';
    const f = fs || state.size;
    const sw = f * (sp('frameOutline') ?? 20) / 100;
    ctx.fillStyle = accent;
    drawWords(line, cx, y, 0, 0, 'fill', false);
    strokeWords(line, cx, y, accent, sw);
    ctx.fillStyle = state.colorTouched ? state.color : contrastText(sp('frameCardC') || '#FFFFFF');
    drawWords(line, cx, y);
  },
  // Bell note card (Reza, 2026-11-23 — his createBellNoteCard code):
  // white text on the dark slate glass card (the card, the bell badge
  // and the hand-drawn line are painted block-level in draw()). A
  // colour picked in the رنگ tab wins; otherwise contrastText keeps it
  // readable on the card colour.
  bell: (line, cx, y) => {
    const c = sp('bellCardC') || '#343b40';
    ctx.fillStyle = state.colorTouched ? state.color : contrastText(c);
    drawWords(line, cx, y);
  },
  // Hearts tape card (Reza, 2026-11-23 — his createHeartsTapeCard
  // code): white text on the dark burgundy card (the card and the
  // hearts tape strip are painted block-level in draw()). A colour
  // picked in the رنگ tab wins; otherwise contrastText keeps it
  // readable on the card colour.
  hearts: (line, cx, y) => {
    const c = sp('heartsCardC') || '#3b0b1f';
    ctx.fillStyle = state.colorTouched ? state.color : contrastText(c);
    drawWords(line, cx, y);
  },
  // Double frame text card (Reza, 2026-11-23 — his
  // createDoubleFrameTextCard code): coral pink text on the dark
  // burgundy inner box (the three frames are painted block-level in
  // draw()). A colour picked in the رنگ tab wins; otherwise his coral
  // pink #ff9ba2 — a fixed design colour, not contrastText, because the
  // pink-on-burgundy pairing is the look.
  doubleFrame: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#ff9ba2';
    drawWords(line, cx, y);
  },
  // Message notification card (Reza, 2026-11-23 — his
  // createMessageNotificationCard code): black text on the light-grey
  // card (the stacked layers + header are painted block-level in
  // draw()). A colour picked in the رنگ tab wins; otherwise
  // contrastText keeps it readable on the card colour.
  msgnotif: (line, cx, y) => {
    const c = sp('msgnotifCardC') || '#e3e4e6';
    ctx.fillStyle = state.colorTouched ? state.color : contrastText(c);
    drawWords(line, cx, y);
  },
  // Stitched card (Reza, 2026-11-23 — his createStitchedCard code):
  // dark brown-red text on the dusty-rose card (the card + stitch
  // border are painted block-level in draw()). A colour picked in the
  // رنگ tab wins; otherwise his #6e1904 — a fixed design colour, not
  // contrastText, because the brown-red-on-rose pairing is the look.
  stitched: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#6e1904';
    drawWords(line, cx, y);
  },
  // Sewing pin card (Reza, 2026-11-23 — his createSewingPinCard
  // code): white text on the olive card (the card + white frame +
  // sewing pin are painted block-level in draw()). A colour picked in
  // the رنگ tab wins; otherwise his #ffffff — a fixed design colour,
  // not contrastText, because the white-on-olive pairing is the look.
  sewingpin: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#ffffff';
    drawWords(line, cx, y);
  },
  // Spiral notepad card (Reza, 2026-11-23 — his createSpiralNotepadCard
  // code): black text on the orange paper (the paper + black frame +
  // spiral binding are painted block-level in draw()). A colour picked
  // in the رنگ tab wins; otherwise his #000000 — a fixed design colour,
  // not contrastText, because the black-on-orange pairing is the look.
  spiral: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#000000';
    drawWords(line, cx, y);
  },
  // Window card (Reza, 2026-11-23 — his createWindowCard code): black
  // text on the white body (the title bar + body + controls are
  // painted block-level in draw()). A colour picked in the رنگ tab
  // wins; otherwise his #000000 — a fixed design colour, not
  // contrastText, because the black-on-white pairing is the look.
  windowcard: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#000000';
    drawWords(line, cx, y);
  },
  // Split window card (Reza, 2026-11-23 — his createSplitWindowCard
  // code): white text on the dark burgundy body (the title bar + body
  // + circles are painted block-level in draw()). A colour picked in
  // the رنگ tab wins; otherwise his #ffffff — a fixed design colour,
  // not contrastText, because the white-on-burgundy pairing is the
  // look.
  splitwindow: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#ffffff';
    drawWords(line, cx, y);
  },
  // Mac window card (Reza, 2026-11-23 — his createMacWindowCard
  // code): black text on the white body (the title bar + body + dots
  // are painted block-level in draw()). A colour picked in the رنگ
  // tab wins; otherwise his #000000 — a fixed design colour, not
  // contrastText, because the black-on-white pairing is the look.
  macwindow: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#000000';
    drawWords(line, cx, y);
  },
  // Heart footer card (Reza, 2026-11-23 — his createHeartFooterCard
  // code): black text on the pink card (the divider + heart are
  // painted block-level in draw()). A colour picked in the رنگ tab
  // wins; otherwise his #000000 — a fixed design colour, not
  // contrastText, because the black-on-pink pairing is the look.
  heart: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#000000';
    drawWords(line, cx, y);
  },
  // Glass notification card (Reza, 2026-11-23 — his
  // createGlassNotificationCard code): white text on the translucent
  // glass panel (the panel + time label are painted block-level in
  // draw()). A colour picked in the رنگ tab wins; otherwise his
  // #ffffff — a fixed design colour, not contrastText, because the
  // white-on-glass pairing is the look.
  glassnotif: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#ffffff';
    drawWords(line, cx, y);
  },
  // Typed input card (Reza, 2026-11-23 — his createTypedInputCard
  // code): black text on the lavender card (the card, border and
  // shadow are painted block-level in draw()). A colour picked in
  // the رنگ tab wins; otherwise his #000000 — a fixed design colour,
  // not contrastText, because the black-on-lavender pairing is the
  // look.
  typed: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#000000';
    drawWords(line, cx, y);
  },
  // Corner accent card (Reza, 2026-11-23 — his createCornerAccentCard
  // code): black text on the light-grey card (the card, border and
  // corner arcs are painted block-level in draw()). A colour picked in
  // the رنگ tab wins; otherwise his #000000 — a fixed design colour,
  // not contrastText, because the black-on-grey pairing is the look.
  corner: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#000000';
    drawWords(line, cx, y);
  },
  // Slanted quote frame card (Reza, 2026-11-23 — his
  // createSlantedQuoteFrameCard code): white text on the page
  // background (the frame paths and quote marks are painted
  // block-level in draw()). A colour picked in the رنگ tab wins;
  // otherwise his #ffffff — a fixed design colour, not contrastText,
  // because the white-on-background pairing is the look, like the
  // quotes style.
  slantquote: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#ffffff';
    drawWords(line, cx, y);
  },
  // Double line text (Reza, 2026-11-23 — his createDoubleLineTextStyle
  // code): white text between two thin lines (the lines are painted
  // block-level in draw()). A colour picked in the رنگ tab wins;
  // otherwise his #ffffff — a fixed design colour, not contrastText,
  // because the white-on-background pairing is the look, like the
  // slantquote style.
  doubleline: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#ffffff';
    drawWords(line, cx, y);
  },
  // Yellow bars banner (Reza, 2026-11-23 — his
  // createYellowBarsBannerStyle code): white text with a black outline
  // between two vertical yellow bars (the bars and the glow are
  // painted block-level in draw()). His two-layer text trick, in
  // canvas form: stroke the glyph in the outline colour first (the
  // fill covers the inner half of the stroke, so the visible outline
  // is half the stroke width — exactly like his paint-order: stroke
  // fill), then fill in white. A colour picked in the رنگ tab wins
  // for the fill; otherwise his #ffffff.
  yellowbars: (line, cx, y, visLw, fs) => {
    const strokeW = fs * 7 / 66; // his -webkit-text-stroke 7px at 66px
    strokeWords(line, cx, y, sp('yellowBarsStrokeC') || '#111111', strokeW);
    ctx.fillStyle = state.colorTouched ? state.color : '#ffffff';
    drawWords(line, cx, y);
  },
  // Gradient bars text (Reza, 2026-11-24 — his
  // createGradientBarsTextStyle code): white text between two
  // vertical gradient bars (the bars are painted block-level in
  // draw()). A colour picked in the رنگ tab wins; otherwise his
  // #ffffff.
  gradbars: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#ffffff';
    drawWords(line, cx, y);
  },
  // Side line text (Reza, 2026-11-24 — his
  // createSideLineTextStyle code): plain white text — the line
  // itself is painted block-level in draw(). A colour picked in
  // the رنگ tab wins; otherwise his #ffffff.
  sideline: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#ffffff';
    drawWords(line, cx, y);
  },
  // Metallic gradient card (Reza, 2026-11-24 — his
  // createMetallicGradientCard code): white text on the metallic
  // gradient card (the card is painted block-level in draw()). A
  // colour picked in the رنگ tab wins; otherwise his #ffffff.
  metallic: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#ffffff';
    drawWords(line, cx, y);
  },
  // Floating shadow card (Reza, 2026-11-24 — his
  // createFloatingShadowCard code): the white text carries his two
  // down-right shadows — the close one (2px 4px, blur 5) and the
  // wider one (4px 8px, blur 12), both scaled by the same intensity
  // as the card's shadow. Each pass draws the text with its shadow;
  // the second pass paints identical text pixels, so only its
  // shadow shows. Both passes are wrapped in save/restore so no
  // shadow leaks into the next line (slider-bug lesson).
  floatshadow: (line, cx, y) => {
    const shadowC = sp('floatShadowC') || '#000000';
    const intensity = (sp('floatShadowO') ?? 78) / 100;
    const fill = state.colorTouched ? state.color : '#ffffff';
    ctx.save();
    ctx.shadowColor = hexToRgba(shadowC, 0.62 * intensity);
    ctx.shadowBlur = 5;
    ctx.shadowOffsetX = 2;
    ctx.shadowOffsetY = 4;
    ctx.fillStyle = fill;
    drawWords(line, cx, y);
    ctx.restore();
    ctx.save();
    ctx.shadowColor = hexToRgba(shadowC, 0.45 * intensity);
    ctx.shadowBlur = 12;
    ctx.shadowOffsetX = 4;
    ctx.shadowOffsetY = 8;
    ctx.fillStyle = fill;
    drawWords(line, cx, y);
    ctx.restore();
  },
  // Glass glow frame card (Reza, 2026-11-24 — his
  // createGlassGlowFrameCard code): the white text carries his
  // four-layer neon glow in the glow colour — 0 0 5px, 13px, 24px
  // and 38px, each scaled by the glow intensity. Each pass draws
  // the text with its glow; the later passes paint identical text
  // pixels, so only the new glow shows. All four passes are wrapped
  // in save/restore so no glow leaks into the next line
  // (slider-bug lesson).
  glowframe: (line, cx, y) => {
    const glowC = sp('glowframeGlowC') || '#9be8ac';
    const intensity = (sp('glowframeGlowO') ?? 85) / 100;
    const fill = state.colorTouched ? state.color : '#ffffff';
    const glows = [
      { blur: 5, a: 0.90 },
      { blur: 13, a: 0.72 },
      { blur: 24, a: 0.46 },
      { blur: 38, a: 0.22 },
    ];
    for (const g of glows) {
      ctx.save();
      ctx.shadowColor = hexToRgba(glowC, g.a * intensity);
      ctx.shadowBlur = g.blur;
      ctx.shadowOffsetX = 0;
      ctx.shadowOffsetY = 0;
      ctx.fillStyle = fill;
      drawWords(line, cx, y);
      ctx.restore();
    }
  },
  // Corner glow frame card (Reza, 2026-11-24 — his
  // createCornerGlowFrameCard code): the text is plain white and
  // crisp — no shadow on it (the glow lives on the frame's corners,
  // painted block-level in draw()). A colour picked in the رنگ tab
  // wins; otherwise his #ffffff.
  cornerglow: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#ffffff';
    drawWords(line, cx, y);
  },
  // Vibrant shadow card (Reza, 2026-11-24 — his
  // createVibrantShadowCard code): the white text carries his
  // small down-right shadow — 2px 3px, blur 4px at intensity 1,
  // alpha 0.36 — scaled by the same intensity knob as the card's
  // shadow. One pass: the shadow is his single textShadow layer.
  // Wrapped in save/restore so no shadow leaks into the next line
  // (slider-bug lesson).
  vibrantshadow: (line, cx, y) => {
    const shadowC = sp('vibrantShadowC') || '#000000';
    const s = Math.max(0, (sp('vibrantShadowO') ?? 100) / 100);
    const fill = state.colorTouched ? state.color : '#ffffff';
    ctx.save();
    ctx.shadowColor = hexToRgba(shadowC, Math.min(0.75, 0.36 * s));
    ctx.shadowBlur = Math.max(2, Math.round(4 * s));
    ctx.shadowOffsetX = 2;
    ctx.shadowOffsetY = 3;
    ctx.fillStyle = fill;
    drawWords(line, cx, y);
    ctx.restore();
  },
  // Glossy glass card (Reza, 2026-11-24 — his
  // createGlossyGlassCard code): plain white text, no shadow —
  // the glass card itself (painted block-level by paintGlossyCard)
  // carries the look.
  glossyglass: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#ffffff';
    drawWords(line, cx, y);
  },
  // Gradient shadow card (Reza, 2026-11-24 — his
  // createGradientShadowCard code): the white text carries his
  // soft shadow — 0 4px, blur 8px, alpha 0.44 × intensity —
  // scaled by the same intensity knob as the card's shadow. One
  // pass: the shadow is his single textShadow layer. Wrapped in
  // save/restore so no shadow leaks into the next line
  // (slider-bug lesson).
  gradientshadow: (line, cx, y) => {
    const s = Math.max(0, Math.min(1, (sp('gradShadowO') ?? 55) / 100));
    const fill = state.colorTouched ? state.color : '#ffffff';
    ctx.save();
    ctx.shadowColor = `rgba(0, 0, 0, ${(0.44 * s).toFixed(3)})`;
    ctx.shadowBlur = 8;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 4;
    ctx.fillStyle = fill;
    drawWords(line, cx, y);
    ctx.restore();
  },
  // Fading shadow text (Reza, 2026-11-24 — his
  // createFadingShadowTextStyle code): the white text carries his
  // two soft shadow layers — the near one (0 0.05em, blur 0.09em,
  // alpha 0.34 × intensity) and the far halo (0 0.13em, blur
  // 0.24em, alpha 0.50 × intensity) — scaled by the same
  // intensity knob as the fade. Each pass draws the same text, so
  // the later pass paints identical pixels and only its shadow
  // shows. Wrapped in save/restore so no shadow leaks into the
  // next line (slider-bug lesson). The fade itself is NOT painted
  // here: it is a block-level mask applied after all lines, in
  // draw() (and in paintFadingSamples), so text and shadow fade
  // together exactly like his masked wrapper.
  fading: (line, cx, y, lw, fs) => {
    const s = Math.max(0, Math.min(1, (sp('fadeShadowO') ?? 65) / 100));
    const fill = state.colorTouched ? state.color : '#ffffff';
    if (s <= 0) {
      ctx.fillStyle = fill;
      drawWords(line, cx, y);
      return;
    }
    const em = fs || 100;
    const shadows = [
      { ox: 0, oy: 0.05 * em, blur: 0.09 * em, a: 0.34 * s },
      { ox: 0, oy: 0.13 * em, blur: 0.24 * em, a: 0.50 * s },
    ];
    for (const sh of shadows) {
      ctx.save();
      ctx.shadowColor = `rgba(0, 0, 0, ${sh.a.toFixed(3)})`;
      ctx.shadowBlur = sh.blur;
      ctx.shadowOffsetX = sh.ox;
      ctx.shadowOffsetY = sh.oy;
      ctx.fillStyle = fill;
      drawWords(line, cx, y);
      ctx.restore();
    }
  },
  // Shiny gold card (Reza, 2026-11-24 — his
  // createShinyGoldCard code): the text is BLACK by default (his
  // textColor), with his faint white halo — 0 0.02em, blur 0.05em,
  // alpha 0.42 — to separate it from the bright metal. One pass:
  // the halo is his single textShadow layer. Wrapped in
  // save/restore so no shadow leaks into the next line
  // (slider-bug lesson). The gold card itself (with its two
  // shine bands and drop shadow) is painted block-level by
  // paintShinyGoldCard.
  shinygold: (line, cx, y, lw, fs) => {
    const fill = state.colorTouched ? state.color : '#000000';
    const em = fs || 100;
    ctx.save();
    ctx.shadowColor = 'rgba(255, 255, 255, 0.42)';
    ctx.shadowBlur = 0.05 * em;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0.02 * em;
    ctx.fillStyle = fill;
    drawWords(line, cx, y);
    ctx.restore();
  },
  // Lifted shadow card (Reza, 2026-11-24 — his
  // createLiftedShadowCard code): plain black text, no shadow — the
  // arched shadow under the card is painted block-level by
  // paintLiftedShadowCard.
  liftedshadow: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#000000';
    drawWords(line, cx, y);
  },
  // Fading sheen ribbon (Reza, 2026-11-24 — his
  // createFadingSheenRibbonStyle code): white text with his two-layer
  // soft shadow — 0.018em/0.04em, blur 0.065em, alpha 0.72 x
  // intensity, plus 0/0.015em, blur 0.025em, alpha 0.45 x intensity.
  // Canvas takes one shadow per pass, so the two layers are two
  // drawWords passes (the fading style's pattern). One pass per
  // layer: the second paints identical glyph pixels on top.
  sheenribbon: (line, cx, y, lw, fs) => {
    const s = Math.max(0, Math.min(1, (sp('sheenShadowO') ?? 50) / 100));
    const fill = state.colorTouched ? state.color : '#ffffff';
    if (s <= 0) {
      ctx.fillStyle = fill;
      drawWords(line, cx, y);
      return;
    }
    const em = fs || 100;
    const shadows = [
      { ox: 0.018 * em, oy: 0.04 * em, blur: 0.065 * em, a: 0.72 * s },
      { ox: 0, oy: 0.015 * em, blur: 0.025 * em, a: 0.45 * s },
    ];
    for (const sh of shadows) {
      ctx.save();
      ctx.shadowColor = `rgba(0, 0, 0, ${sh.a.toFixed(3)})`;
      ctx.shadowBlur = sh.blur;
      ctx.shadowOffsetX = sh.ox;
      ctx.shadowOffsetY = sh.oy;
      ctx.fillStyle = fill;
      drawWords(line, cx, y);
      ctx.restore();
    }
  },
  // Emerald gradient card (Reza, 2026-11-24 — his
  // createEmeraldGradientCard code): white text with his two-layer
  // deep shadow — 0/0.06em, blur 0.085em, alpha 0.84 x intensity,
  // plus 0/0.025em, blur 0.03em, alpha 0.62 x intensity. Canvas takes
  // one shadow per pass, so the two layers are two drawWords passes
  // (the fading style's pattern). One knob (emeraldShadowO) drives
  // both this text shadow and the card's drop shadow, like his single
  // shadowIntensity.
  emeraldgradient: (line, cx, y, lw, fs) => {
    const s = Math.max(0, Math.min(1, (sp('emeraldShadowO') ?? 65) / 100));
    const fill = state.colorTouched ? state.color : '#ffffff';
    if (s <= 0) {
      ctx.fillStyle = fill;
      drawWords(line, cx, y);
      return;
    }
    const em = fs || 100;
    const shadows = [
      { ox: 0, oy: 0.06 * em, blur: 0.085 * em, a: 0.84 * s },
      { ox: 0, oy: 0.025 * em, blur: 0.03 * em, a: 0.62 * s },
    ];
    for (const sh of shadows) {
      ctx.save();
      ctx.shadowColor = `rgba(0, 0, 0, ${sh.a.toFixed(3)})`;
      ctx.shadowBlur = sh.blur;
      ctx.shadowOffsetX = sh.ox;
      ctx.shadowOffsetY = sh.oy;
      ctx.fillStyle = fill;
      drawWords(line, cx, y);
      ctx.restore();
    }
  },
  // Sharp highlight box (Reza, 2026-11-24 — his
  // createSharpHighlightBox code): white text with his two-layer
  // sharp shadow — 0/0.055em, blur 0.075em, alpha 0.82 x intensity,
  // plus 0/0.022em, blur 0.024em, alpha 0.64 x intensity. Canvas takes
  // one shadow per pass, so the two layers are two drawWords passes
  // (the fading style's pattern).
  sharphighlight: (line, cx, y, lw, fs) => {
    const s = Math.max(0, Math.min(1, (sp('sharpShadowO') ?? 72) / 100));
    const fill = state.colorTouched ? state.color : '#ffffff';
    if (s <= 0) {
      ctx.fillStyle = fill;
      drawWords(line, cx, y);
      return;
    }
    const em = fs || 100;
    const shadows = [
      { ox: 0, oy: 0.055 * em, blur: 0.075 * em, a: 0.82 * s },
      { ox: 0, oy: 0.022 * em, blur: 0.024 * em, a: 0.64 * s },
    ];
    for (const sh of shadows) {
      ctx.save();
      ctx.shadowColor = `rgba(0, 0, 0, ${sh.a.toFixed(3)})`;
      ctx.shadowBlur = sh.blur;
      ctx.shadowOffsetX = sh.ox;
      ctx.shadowOffsetY = sh.oy;
      ctx.fillStyle = fill;
      drawWords(line, cx, y);
      ctx.restore();
    }
  },
  // Glass outline text (Reza, 2026-11-24 — his
  // createGlassOutlineTextStyle code): layered canvas text, no card.
  // Layer 1, the mask: the glyph shapes, solid. Layer 2, the outer
  // ring: a thick mitered stroke (0.132em, miterLimit 3) in the
  // stroke colour, filled too so the soft shadow takes the full
  // glyph shape (0/0.088em, blur 0.16em, alpha 0.70 x intensity),
  // redrawn crisp without the shadow, then the mask cut out of it
  // (destination-out) so only the ring and its shadow remain and the
  // real background shows through the middle of the letters. Layer
  // 3, the glass fill: the mask clipped (source-in) to his diagonal
  // gradient, opaque at the bottom-left fading to 0.50 at the
  // top-right. Layer 4, the inner rim: the inverted mask shifted in
  // 16 directions at 0.042em (plus 8 more at half width when the rim
  // is wider than 2.2px), clipped back inside the glyphs
  // (destination-in) and coloured with his white-to-silver diagonal
  // gradient. Every layer is built per line on a small offscreen
  // canvas and composited onto the main canvas; drawWords paints
  // the mask and the stroke, so word spacing, justification and
  // letter spacing match the other styles exactly. His
  // 0.34em/0.30em/0.44em padding is the offscreen margin around each
  // line, not a user knob, plus a 0.25em shadow margin (2026-11-24
  // fix) so the outline shadow is never cropped at the layer edge.
  // The text colour is the رنگ tab's colour
  // (white by default), like the other text styles.
  glassoutline: (line, cx, y, lw, fs) => {
    const em = fs || 100;
    const words = line.split(' ').filter((w) => w !== '');
    if (!words.length) return;
    const s = Math.max(0, Math.min(1, (sp('glassoutlineShadowO') ?? 78) / 100));
    const textC = flatColor(state.colorTouched ? state.color : '#ffffff');
    const strokeC = sp('glassoutlineStrokeC') || '#000000';
    const rimC = sp('glassoutlineRimC') || '#dcdcdc';
    const [tr, tg, tb] = hexToRgb(textC);
    const [rr, rg, rb] = hexToRgb(rimC);
    // The line's glyph box, exactly as drawWords places it. draw()
    // paints with textBaseline 'middle', so y is the line's vertical
    // centre — the offscreen top is set so the glyph box centres on y.
    const visW = lineWidth(line) + lineJustifyGap * (words.length - 1);
    const m = ctx.measureText(line);
    const ascent = (m.actualBoundingBoxAscent > 0 ? m.actualBoundingBoxAscent : em * 0.78);
    const descent = (m.actualBoundingBoxDescent > 0 ? m.actualBoundingBoxDescent : em * 0.38);
    const padX = Math.ceil(em * 0.34), padTop = Math.ceil(em * 0.30), padBot = Math.ceil(em * 0.44);
    // Shadow margin (Reza, 2026-11-24 — the shadow above the text
    // was cropped): the outline stroke (0.066em past the glyphs)
    // plus the shadow blur (0.16em core, with a soft tail to ~2x)
    // reaches ~0.39em past the glyph box, but the offscreen canvas
    // only had his 0.30em pad on top — the faint tail was cut at the
    // canvas edge, a hard line in the soft shadow above the letters.
    // The layers get an extra 0.25em on every side so the whole
    // shadow fits; the text itself does not move.
    const sh = Math.ceil(em * 0.25);
    const tx = padX + sh, ty = padTop + sh;
    const w = Math.ceil(visW) + tx * 2, h = Math.ceil(ascent + descent) + ty + padBot + sh;
    const ox = cx - visW / 2 - tx, oy = y - (ascent + descent) / 2 - ty;
    const ocx = tx + visW / 2, obaseline = ty + ascent;
    // A layer canvas carrying the main canvas's font state, so
    // drawWords paints identical glyphs on it.
    const layer = () => {
      const c = document.createElement('canvas');
      c.width = Math.max(1, w);
      c.height = Math.max(1, h);
      const g = c.getContext('2d');
      g.font = ctx.font;
      g.textBaseline = 'alphabetic';
      g.direction = ctx.direction;
      if ('letterSpacing' in g) g.letterSpacing = ctx.letterSpacing;
      return { c, g };
    };
    // drawWords reads the global ctx, so swap it onto the layer for
    // the call. textFill false: the fill colour is set explicitly
    // before each call and must not be replaced by a gradient.
    const prevCtx = ctx;
    const paintWords = (g, mode) => {
      ctx = g;
      drawWords(line, ocx, obaseline, 0, 0, mode, false);
      ctx = prevCtx;
    };
    // 1. The mask: the glyph shapes, solid black.
    const mask = layer();
    mask.g.fillStyle = '#000000';
    paintWords(mask.g, 'fill');
    // 2. The outer ring: thick mitered stroke + fill with the soft
    // shadow, redrawn crisp, then the glyph interiors cut out.
    const outer = layer();
    outer.g.lineJoin = 'miter';
    outer.g.miterLimit = 3;
    outer.g.lineWidth = em * 0.132;
    outer.g.strokeStyle = strokeC;
    outer.g.fillStyle = strokeC;
    if (s > 0) {
      outer.g.shadowColor = `rgba(0, 0, 0, ${(0.70 * s).toFixed(3)})`;
      outer.g.shadowBlur = em * 0.16;
      outer.g.shadowOffsetX = 0;
      outer.g.shadowOffsetY = em * 0.088;
    }
    paintWords(outer.g, 'stroke');
    paintWords(outer.g, 'fill');
    outer.g.shadowColor = 'transparent';
    outer.g.shadowBlur = 0;
    outer.g.shadowOffsetX = 0;
    outer.g.shadowOffsetY = 0;
    paintWords(outer.g, 'stroke');
    outer.g.globalCompositeOperation = 'destination-out';
    outer.g.drawImage(mask.c, 0, 0);
    // 3. The glass fill: the mask clipped to his diagonal gradient,
    // bottom-left (opaque) to top-right (0.50).
    const fillL = layer();
    fillL.g.drawImage(mask.c, 0, 0);
    fillL.g.globalCompositeOperation = 'source-in';
    const fillGrad = fillL.g.createLinearGradient(tx, ty + ascent + descent, tx + visW, ty);
    fillGrad.addColorStop(0.00, `rgba(${tr}, ${tg}, ${tb}, 1)`);
    fillGrad.addColorStop(0.28, `rgba(${tr}, ${tg}, ${tb}, 0.96)`);
    fillGrad.addColorStop(0.52, `rgba(${tr}, ${tg}, ${tb}, 0.68)`);
    fillGrad.addColorStop(0.76, `rgba(${tr}, ${tg}, ${tb}, 0.54)`);
    fillGrad.addColorStop(1.00, `rgba(${tr}, ${tg}, ${tb}, 0.50)`);
    fillL.g.fillStyle = fillGrad;
    fillL.g.fillRect(0, 0, w, h);
    // 4. The inner rim: the inverted mask shifted in 16 directions
    // at the rim width (plus 8 at half width when it is wider than
    // 2.2px), clipped back inside the glyphs, coloured with his
    // white-to-silver diagonal gradient.
    const inv = layer();
    inv.g.fillStyle = '#000000';
    inv.g.fillRect(0, 0, w, h);
    inv.g.globalCompositeOperation = 'destination-out';
    inv.g.drawImage(mask.c, 0, 0);
    const rim = layer();
    const rimWidth = Math.max(1.5, em * 0.042);
    const steps = 16;
    for (let i = 0; i < steps; i++) {
      const angle = (i / steps) * Math.PI * 2;
      rim.g.drawImage(inv.c, Math.cos(angle) * rimWidth, Math.sin(angle) * rimWidth);
    }
    if (rimWidth > 2.2) {
      for (let i = 0; i < 8; i++) {
        const angle = (i / 8) * Math.PI * 2;
        rim.g.drawImage(inv.c, Math.cos(angle) * rimWidth * 0.52, Math.sin(angle) * rimWidth * 0.52);
      }
    }
    rim.g.globalCompositeOperation = 'destination-in';
    rim.g.drawImage(mask.c, 0, 0);
    rim.g.globalCompositeOperation = 'source-in';
    const rimGrad = rim.g.createLinearGradient(tx, ty + ascent + descent, tx + visW, ty);
    rimGrad.addColorStop(0.00, `rgba(${tr}, ${tg}, ${tb}, 1)`);
    rimGrad.addColorStop(0.32, `rgba(${tr}, ${tg}, ${tb}, 0.94)`);
    rimGrad.addColorStop(0.68, `rgba(${rr}, ${rg}, ${rb}, 0.78)`);
    rimGrad.addColorStop(1.00, `rgba(${rr}, ${rg}, ${rb}, 0.74)`);
    rim.g.fillStyle = rimGrad;
    rim.g.fillRect(0, 0, w, h);
    // Composite the three layers onto the main canvas.
    ctx.save();
    ctx.drawImage(outer.c, ox, oy);
    ctx.drawImage(fillL.c, ox, oy);
    ctx.drawImage(rim.c, ox, oy);
    ctx.restore();
  },
  // Layered gold text (Reza, 2026-11-24 — his
  // createLayeredGoldTextStyle code): layered canvas text, no card.
  // The outer double outline: a thick yellow stroke (0.194em) in
  // the accent colour with the soft shadow (0/0.095em, blur 0.16em,
  // alpha 0.72 x intensity), redrawn crisp, then a thick near-black
  // stroke (0.136em) inside it, with the glyph interiors cut out
  // (destination-out) so only the two rings and their shadow remain.
  // The inside of the letters is five concentric rings, from the
  // edge inward — bright accent, groove, mid-bright accent, groove,
  // bright centre — built by eroding the inverted mask in four steps
  // (0.020/0.015/0.024/0.015em, each a 16-direction dilation plus 8
  // at half radius when wider than 1.2px) and painting each inset
  // region in turn, then faded diagonally (opaque bottom-left to
  // 0.64 top-right). Every layer is built per line on a small
  // offscreen canvas and composited onto the main canvas; drawWords
  // paints the mask and the strokes, so word spacing, justification
  // and letter spacing match the other styles exactly. His
  // 0.38em/0.34em/0.46em padding is the offscreen margin around each
  // line, not a user knob, plus a 0.25em shadow margin (glassoutline
  // lesson) so the outline shadow is never cropped at the layer
  // edge. The accent is the رنگ tab's colour (yellow #ffea38 by
  // default), like the other text styles. Defaults follow the usage
  // example Reza approved (2026-11-24): groove #fef700, shadow 66%
  // — not the signature's #a88e14 / 78%.
  layeredgold: (line, cx, y, lw, fs) => {
    const em = fs || 100;
    const words = line.split(' ').filter((w) => w !== '');
    if (!words.length) return;
    const s = Math.max(0, Math.min(1, (sp('layeredgoldShadowO') ?? 66) / 100));
    const accentC = flatColor(state.colorTouched ? state.color : '#ffea38');
    const strokeC = sp('layeredgoldStrokeC') || '#080805';
    const grooveC = sp('layeredgoldGrooveC') || '#fef700';
    const [ar, ag, ab] = hexToRgb(accentC);
    const [gr, gg, gb] = hexToRgb(grooveC);
    // The line's glyph box, exactly as drawWords places it. draw()
    // paints with textBaseline 'middle', so y is the line's vertical
    // centre — the offscreen top is set so the glyph box centres on y.
    const visW = lineWidth(line) + lineJustifyGap * (words.length - 1);
    const m = ctx.measureText(line);
    const ascent = (m.actualBoundingBoxAscent > 0 ? m.actualBoundingBoxAscent : em * 0.78);
    const descent = (m.actualBoundingBoxDescent > 0 ? m.actualBoundingBoxDescent : em * 0.38);
    const padX = Math.ceil(em * 0.38), padTop = Math.ceil(em * 0.34), padBot = Math.ceil(em * 0.46);
    const sh = Math.ceil(em * 0.25);
    const tx = padX + sh, ty = padTop + sh;
    const w = Math.ceil(visW) + tx * 2, h = Math.ceil(ascent + descent) + ty + padBot + sh;
    const ox = cx - visW / 2 - tx, oy = y - (ascent + descent) / 2 - ty;
    const ocx = tx + visW / 2, obaseline = ty + ascent;
    // A layer canvas carrying the main canvas's font state, so
    // drawWords paints identical glyphs on it.
    const layer = () => {
      const c = document.createElement('canvas');
      c.width = Math.max(1, w);
      c.height = Math.max(1, h);
      const g = c.getContext('2d');
      g.font = ctx.font;
      g.textBaseline = 'alphabetic';
      g.direction = ctx.direction;
      if ('letterSpacing' in g) g.letterSpacing = ctx.letterSpacing;
      return { c, g };
    };
    // drawWords reads the global ctx, so swap it onto the layer for
    // the call. textFill false: the fill colour is set explicitly
    // before each call and must not be replaced by a gradient.
    const prevCtx = ctx;
    const paintWords = (g, mode) => {
      ctx = g;
      drawWords(line, ocx, obaseline, 0, 0, mode, false);
      ctx = prevCtx;
    };
    // 1. The mask: the glyph shapes, solid black.
    const mask = layer();
    mask.g.fillStyle = '#000000';
    paintWords(mask.g, 'fill');
    // 2. The outer double outline: thick yellow stroke + fill with
    // the soft shadow, redrawn crisp, then the near-black stroke
    // inside it; the glyph interiors are cut out afterwards.
    const outer = layer();
    outer.g.lineJoin = 'miter';
    outer.g.miterLimit = 3;
    outer.g.lineWidth = em * 0.194;
    outer.g.strokeStyle = accentC;
    outer.g.fillStyle = accentC;
    if (s > 0) {
      outer.g.shadowColor = `rgba(0, 0, 0, ${(0.72 * s).toFixed(3)})`;
      outer.g.shadowBlur = em * 0.16;
      outer.g.shadowOffsetX = 0;
      outer.g.shadowOffsetY = em * 0.095;
    }
    paintWords(outer.g, 'stroke');
    paintWords(outer.g, 'fill');
    outer.g.shadowColor = 'transparent';
    outer.g.shadowBlur = 0;
    outer.g.shadowOffsetX = 0;
    outer.g.shadowOffsetY = 0;
    paintWords(outer.g, 'stroke');
    outer.g.lineWidth = em * 0.136;
    outer.g.strokeStyle = strokeC;
    paintWords(outer.g, 'stroke');
    outer.g.globalCompositeOperation = 'destination-out';
    outer.g.drawImage(mask.c, 0, 0);
    // 3. The inverted mask, eroded in four chained steps for the
    // concentric rings. dilate unions the source with 16 shifted
    // copies at the radius (plus 8 at half radius when it is wider
    // than 1.2px), so each cut is the glyphs eroded that much deeper.
    const inv = layer();
    inv.g.fillStyle = '#000000';
    inv.g.fillRect(0, 0, w, h);
    inv.g.globalCompositeOperation = 'destination-out';
    inv.g.drawImage(mask.c, 0, 0);
    const dilate = (src, radiusPx) => {
      const out = layer();
      out.g.drawImage(src, 0, 0);
      const steps = 16;
      for (let i = 0; i < steps; i++) {
        const angle = (i / steps) * Math.PI * 2;
        out.g.drawImage(src, Math.cos(angle) * radiusPx, Math.sin(angle) * radiusPx);
      }
      if (radiusPx > 1.2) {
        for (let i = 0; i < 8; i++) {
          const angle = (i / 8) * Math.PI * 2;
          out.g.drawImage(src, Math.cos(angle) * radiusPx * 0.5, Math.sin(angle) * radiusPx * 0.5);
        }
      }
      return out.c;
    };
    const step1 = Math.max(1.1, em * 0.020);
    const step2 = Math.max(0.9, em * 0.015);
    const step3 = Math.max(1.2, em * 0.024);
    const step4 = Math.max(0.9, em * 0.015);
    const cut1 = dilate(inv.c, step1);
    const cut2 = dilate(cut1, step2);
    const cut3 = dilate(cut2, step3);
    const cut4 = dilate(cut3, step4);
    // 4. The concentric gold rings inside the glyphs, from the edge
    // inward: bright ring, groove, mid-bright ring, groove, bright
    // centre. Each inset region is the mask minus one cut, painted
    // in turn onto the inner layer.
    const inner = layer();
    const brightRingStyle = `rgb(${ar}, ${ag}, ${ab})`;
    const midBrightStyle = `rgb(${Math.min(255, Math.round(ar * 0.96 + 8))}, ${Math.min(255, Math.round(ag * 0.95 + 6))}, ${Math.min(255, Math.round(ab * 0.92 + 10))})`;
    const grooveGrad = inner.g.createLinearGradient(tx, ty + ascent + descent, tx + visW, ty);
    grooveGrad.addColorStop(0.00, `rgba(${Math.round((ar + gr) / 2)}, ${Math.round((ag + gg) / 2)}, ${Math.round((ab + gb) / 2)}, 0.92)`);
    grooveGrad.addColorStop(0.55, `rgba(${gr}, ${gg}, ${gb}, 0.88)`);
    grooveGrad.addColorStop(1.00, `rgba(${gr}, ${gg}, ${gb}, 0.80)`);
    const paintInset = (cutCanvas, fillStyle) => {
      const region = layer();
      region.g.drawImage(mask.c, 0, 0);
      if (cutCanvas) {
        region.g.globalCompositeOperation = 'destination-out';
        region.g.drawImage(cutCanvas, 0, 0);
      }
      region.g.globalCompositeOperation = 'source-in';
      region.g.fillStyle = fillStyle;
      region.g.fillRect(0, 0, w, h);
      inner.g.drawImage(region.c, 0, 0);
    };
    paintInset(null, brightRingStyle);
    paintInset(cut1, grooveGrad);
    paintInset(cut2, midBrightStyle);
    paintInset(cut3, grooveGrad);
    paintInset(cut4, brightRingStyle);
    // Diagonal alpha fade over the rings: vivid at the bottom-left,
    // 0.64 at the top-right.
    inner.g.globalCompositeOperation = 'destination-in';
    const alphaMask = inner.g.createLinearGradient(tx, ty + ascent + descent, tx + visW, ty);
    alphaMask.addColorStop(0.00, 'rgba(0, 0, 0, 1)');
    alphaMask.addColorStop(0.32, 'rgba(0, 0, 0, 0.97)');
    alphaMask.addColorStop(0.58, 'rgba(0, 0, 0, 0.78)');
    alphaMask.addColorStop(0.82, 'rgba(0, 0, 0, 0.68)');
    alphaMask.addColorStop(1.00, 'rgba(0, 0, 0, 0.64)');
    inner.g.fillStyle = alphaMask;
    inner.g.fillRect(0, 0, w, h);
    // Composite the two layers onto the main canvas.
    ctx.save();
    ctx.drawImage(outer.c, ox, oy);
    ctx.drawImage(inner.c, ox, oy);
    ctx.restore();
  },
  // Metallic gold text (Reza, 2026-11-24 — his
  // createMetallicGoldTextStyle code): text-only, no card. The text
  // is a horizontal metallic gradient clipped to the glyphs —
  // edge 0%, soft edge 20%, mid 42%, highlight 59%, mid 78%,
  // edge 100% along a 102deg axis (mostly horizontal, slightly
  // downward) — with a two-layer soft shadow behind it, painted as
  // two drawWords passes since canvas takes one shadow per pass
  // (emerald precedent): a large soft shadow (offset 0.025em/
  // 0.075em, blur 0.105em, alpha 0.64 x intensity) and a small
  // tight one (offset 0/0.03em, blur 0.045em, alpha 0.34 x
  // intensity). The mid colour mixes highlight and edge at 0.56
  // (rgb 212,199,59) and the soft edge at 0.14 (rgb 172,158,46),
  // both computed live from the knobs so they follow any colour
  // change. The gradient spans the line's box including his
  // 0.18em/0.1em span padding, exactly as his background-clip:text
  // layer does. The رنگ tab's colour does not apply here — the
  // gold gradient IS the text, like his code (transparent fill,
  // gradient clipped to the glyphs). Shadow intensity default 66%
  // follows his usage example (the signature says 0.65), the same
  // rule he approved for layeredgold.
  metallicgold: (line, cx, y, lw, fs) => {
    const em = fs || 100;
    const words = line.split(' ').filter((w) => w !== '');
    if (!words.length) return;
    const s = Math.max(0, Math.min(1, (sp('metallicgoldShadowO') ?? 66) / 100));
    const highlightC = sp('metallicgoldHighlightC') || '#fff148';
    const edgeC = sp('metallicgoldEdgeC') || '#9e912a';
    const shadowC = sp('metallicgoldShadowC') || '#000000';
    const [hr, hg, hb] = hexToRgb(highlightC);
    const [er, eg, eb] = hexToRgb(edgeC);
    const [sr, sg, sb] = hexToRgb(shadowC);
    // His mixHex(highlight, edge, weight): highlight*weight +
    // edge*(1-weight), rounded per channel.
    const mix = (weight) => `rgb(${Math.round(hr * weight + er * (1 - weight))}, ${Math.round(hg * weight + eg * (1 - weight))}, ${Math.round(hb * weight + eb * (1 - weight))})`;
    const midColor = mix(0.56);
    const softEdgeColor = mix(0.14);
    const visW = lineWidth(line) + lineJustifyGap * (words.length - 1);
    const m = ctx.measureText(line);
    const ascent = (m.actualBoundingBoxAscent > 0 ? m.actualBoundingBoxAscent : em * 0.78);
    const descent = (m.actualBoundingBoxDescent > 0 ? m.actualBoundingBoxDescent : em * 0.38);
    // His span padding: 0.18em top/bottom, 0.1em left/right.
    const padX = em * 0.1, padTop = em * 0.18, padBot = em * 0.18;
    const boxW = visW + padX * 2;
    const boxH = ascent + descent + padTop + padBot;
    const boxCx = cx, boxCy = y;
    // CSS linear-gradient(102deg): the gradient axis points 102deg
    // clockwise from "up", i.e. (sin 102deg, -cos 102deg) in
    // screen coordinates — mostly rightward, slightly downward.
    // The axis length is the box's projection onto that direction,
    // so the gradient exactly covers the box.
    const dirX = Math.sin(102 * Math.PI / 180);
    const dirY = -Math.cos(102 * Math.PI / 180);
    const axisLen = Math.abs(boxW * dirX) + Math.abs(boxH * dirY);
    const grad = ctx.createLinearGradient(
      boxCx - dirX * axisLen / 2, boxCy - dirY * axisLen / 2,
      boxCx + dirX * axisLen / 2, boxCy + dirY * axisLen / 2
    );
    grad.addColorStop(0.00, edgeC);
    grad.addColorStop(0.20, softEdgeColor);
    grad.addColorStop(0.42, midColor);
    grad.addColorStop(0.59, highlightC);
    grad.addColorStop(0.78, midColor);
    grad.addColorStop(1.00, edgeC);
    // Two shadow passes, then the gradient fill on top of its own
    // shadow — the same layering as his DOM (shadow span behind the
    // metallic span). textFill false: the fill is the gradient set
    // here, not the رنگ tab's colour.
    const prevCtx = ctx;
    const paintWords = (g) => {
      ctx = g;
      drawWords(line, cx, y, 0, 0, 'fill', false);
      ctx = prevCtx;
    };
    ctx.save();
    ctx.fillStyle = grad;
    if (s > 0) {
      ctx.shadowColor = `rgba(${sr}, ${sg}, ${sb}, ${(0.64 * s).toFixed(3)})`;
      ctx.shadowBlur = em * 0.105;
      ctx.shadowOffsetX = em * 0.025;
      ctx.shadowOffsetY = em * 0.075;
      paintWords(ctx);
      ctx.shadowColor = `rgba(${sr}, ${sg}, ${sb}, ${(0.34 * s).toFixed(3)})`;
      ctx.shadowBlur = em * 0.045;
      ctx.shadowOffsetX = 0;
      ctx.shadowOffsetY = em * 0.03;
      paintWords(ctx);
    }
    ctx.shadowColor = 'transparent';
    ctx.shadowBlur = 0;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;
    paintWords(ctx);
    ctx.restore();
  },
  // Messages frame: black text on the light-grey content area (the
  // card + green Messages header are painted block-level in draw()).
  // A colour picked in the رنگ tab wins; if the content colour is
  // changed, contrastText keeps the text readable on it.
  message: (line, cx, y) => {
    const c = sp('messageC') || '#E5E5EA';
    ctx.fillStyle = state.colorTouched ? state.color
      : c.toUpperCase() === '#E5E5EA' ? '#000000' : contrastText(c);
    drawWords(line, cx, y);
  },
  // Halo: white text on a solid red box — ONE box per line (Reza,
  // 2026-11-22: two lines must not share a single box), each hugging
  // its own line's width. The box is painted here per line via bgBox
  // (sharp corners, side pads ~0.29x of fs, height 1.34x of fs so two
  // boxes never overlap at the default line height — the gap between
  // them is 0.06x of fs, and «فاصله خطوط» widens it). Then the shadow
  // is two passes in the dark maroon: (A) a soft halo hugging the
  // letters — the shadow-colour text at the line position with a big
  // blur, no offset; (B) a sharper copy offset down-right. Both use
  // textFill=false so a gradient text colour cannot leak into the
  // shadow layers. The white text on top covers the solid shadow
  // glyphs, leaving the halo and the offset shadow visible around them.
  halo: (line, cx, y, lw, fs) => {
    bgBox(cx, y, lw, fs, { fill: sp('haloBoxC'), radius: 0, padX: fs * 0.29, padY: fs * 0.1 });
    const sh = sp('haloShadowC');
    const off = fs * sp('haloOffset') / 100;
    const blur = fs * sp('haloBlur') / 100;
    ctx.save();
    ctx.shadowColor = sh; ctx.shadowBlur = blur;
    ctx.fillStyle = sh;
    drawWords(line, cx, y, 0, 0, 'fill', false);
    ctx.restore();
    ctx.save();
    ctx.shadowColor = sh; ctx.shadowBlur = blur * 0.35;
    ctx.fillStyle = sh;
    drawWords(line, cx + off * 0.5, y + off, 0, 0, 'fill', false);
    ctx.restore();
    ctx.fillStyle = state.colorTouched ? state.color : '#FFFFFF';
    drawWords(line, cx, y);
  },
  // Message bubble: white text on the blue bubble (the bubble + tail
  // are painted block-level in draw()). A colour picked in the رنگ
  // tab wins.
  msgbubble: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#FFFFFF';
    drawWords(line, cx, y);
  },
  dropbubble: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#FFFFFF';
    drawWords(line, cx, y);
  },
  brushstroke: (line, cx, y) => {
    ctx.fillStyle = state.colorTouched ? state.color : '#FFFFFF';
    drawWords(line, cx, y);
  },
};

// Text alignment happens INSIDE the text block, which stays centred on
// the canvas: وسط‌چین centres each line; راست‌چین lines every line's
// right edge up with the widest line's right edge, چپ‌چین every line's
// left edge with the widest line's left edge. هم‌تراز (justify) stretches
// every line that already covers at least 60% of the block to the
// block's full width (gap > 0 means this line is stretched, so its
// centre is the block centre); a shorter line stays natural and anchors
// to the start side (right for RTL, left for LTR). A single line never moves.
function alignCx(lw, maxLw, line = '', gap = 0, cx = (canvas.width || 1080) / 2) {
  if (state.align === 'right') return cx + maxLw / 2 - lw / 2;
  if (state.align === 'left') return cx - maxLw / 2 + lw / 2;
  if (state.align === 'justify') {
    if (gap > 0) return cx;
    return isRTLText(line) ? cx + maxLw / 2 - lw / 2 : cx - maxLw / 2 + lw / 2;
  }
  return cx;
}

// Extra px added to each word gap when the alignment is justify: the
// line is stretched to the block's full width. A line is only stretched
// when it already covers at least 60% of the block — stretching a much
// shorter line would leave absurd gaps between its few words (e.g. a
// two-word last line «می کنم»). Single-word lines have no gap to
// stretch. The last line of a paragraph stretches too when it is long
// enough — that is the point of justify here: two Enter-separated
// lines of similar length end up the same length.
let lineJustifyGap = 0;
function justifyGap(line, lw, maxLw) {
  if (state.align !== 'justify') return 0;
  const words = line.split(' ').filter((w) => w !== '');
  if (words.length < 2) return 0;
  if (lw < maxLw * 0.6) return 0;
  const extra = maxLw - lw;
  if (extra <= 0) return 0;
  return extra / (words.length - 1);
}

// The text block's rect from the last draw (canvas px): centre, half-size
// and the rotation scales — used by tap-to-dismiss below.
let lastBlock = null;

// Caret position for a text offset p: which visual line it is on, the
// x of the char boundary and the line's centre y. Follows the same
// ranges/widths the selection highlight uses, so the caret always sits
// on the visible glyphs. A p in a gap (the space/newline between two
// lines) lands at the end of the upper line; p at a line's start lands
// at the start of that line.
function caretGeometry(p, lineRanges, lines, maxLw, lineHeight, blockH, h, gaps = null, cx = (canvas.width || 1080) / 2) {
  let li = 0;
  for (let i = 0; i < lineRanges.length; i++) {
    if (lineRanges[i].start <= p) li = i; else break;
  }
  const lr = lineRanges[li];
  const line = lines[li];
  const n = Math.max(0, Math.min(p - lr.start, line.length));
  const lw = lineWidth(line);
  const gap = gaps ? gaps[li] || 0 : 0;
  const lcx = alignCx(lw, maxLw, line, gap, cx);
  const y = h / 2 - blockH / 2 + lineHeight / 2 + li * lineHeight;
  const visW = lw + gap * Math.max(0, line.split(' ').filter((w) => w !== '').length - 1);
  const x = isRTLText(line) ? lcx + visW / 2 - prefixWidth(line, n, gap) : lcx - visW / 2 + prefixWidth(line, n, gap);
  return { x, y, li, n };
}

// The tweet card's chrome (avatar, name, handle, X logo, footer) is
// fixed at the default main size (110) — it does NOT follow the side
// size rail. Only the body text follows the rail (Reza, 2026-11-21:
// the rail used to scale the whole card and mess up the layout).
const TWEET_CHROME_FS = 110;

// Minimum size of the tweet card: at least as wide as its chrome — the
// header row (avatar + name/handle + X logo) and the footer line,
// measured at their own font sizes — and at least as tall as one
// full-size body line. Without it, a small body text (tweetTextSize <
// 100%) shrinks the card until the name runs into the X logo and the
// footer is clipped (Reza's screenshot, 2026-11-21). The caller's
// ctx.font is restored.
function tweetMinSize(fs) {
  const name = (sp('tweetName') || '').trim() || 'FontStory';
  let handle = (sp('tweetHandle') || '').trim() || '@fontstory';
  if (!handle.startsWith('@')) handle = '@' + handle;
  const likes = (sp('tweetLikes') || '').trim() || '4.1k';
  const replies = (sp('tweetReplies') || '').trim() || '18';
  const prevFont = ctx.font;
  ctx.font = `700 ${fs * 0.42}px 'Vazir', system-ui, sans-serif`;
  const nameW = ctx.measureText(name).width;
  ctx.font = `400 ${fs * 0.34}px 'Vazir', system-ui, sans-serif`;
  const handleW = ctx.measureText(handle).width;
  ctx.font = `400 ${fs * 0.32}px 'Vazir', system-ui, sans-serif`;
  const footerW = ctx.measureText(`${likes} likes  ${replies} replies`).width;
  ctx.font = prevFont;
  const av = fs * 0.8, logoSize = fs * 0.5; // same as tweetLayout
  const padLeft = Math.max(0, sp('tweetPadLeft') ?? 56), padRight = Math.max(0, sp('tweetPadRight') ?? 56);
  return {
    minW: Math.max(padLeft + padRight + av + 16 + Math.max(nameW, handleW) + 24 + logoSize, padLeft + padRight + footerW),
    minBlockH: fs * state.lineHeight,
  };
}

// Geometry of the tweet card (black rounded card with an X-post header
// and a likes/replies footer) around the text block. All chrome scales
// with the font size, so the card keeps its proportions at any size.
// cx is the block centre x, h the canvas height. minW/minBlockH (from
// tweetMinSize) keep a small body text from collapsing the card.
// rtl mirrors the header with the text direction (Reza, 2026-11-21):
// RTL text -> avatar left, X logo right; LTR text -> avatar right, X
// logo left. blockShift moves the text block so its start edge sits
// exactly under the logo — the block's right edge under the logo on the
// right for RTL, its left edge under the logo on the left for LTR; zero
// when the card is exactly as wide as the text.
function tweetLayout(fs, maxLw, blockH, lineHeight, h, cx, minW = 0, minBlockH = 0, rtl = true) {
  // Card padding: the outer top/bottom spaces are knobs now
  // (tweetPadTop/tweetPadBottom, 2026-11-24, defaults = his 0.45em).
  // The 2026-11-21 adjustable-padding round was reverted because it
  // broke the card's structure — this one only swaps the two outer
  // constants for knob reads. The card's
  // SIZE is the adjustable part: a default size (760x480, about the
  // card in his screenshot) that the content can grow past, adjustable
  // with the «عرض کارت» / «ارتفاع کارت» sliders in the style sheet.
  // Side padding: two knobs (2026-11-24), defaults = the old symmetric
  // padding; padX stays as their average for the symmetric chrome.
  const padLeft = Math.max(0, sp('tweetPadLeft') ?? 56);
  const padRight = Math.max(0, sp('tweetPadRight') ?? 56);
  const padX = (padLeft + padRight) / 2;
  const padTop = Math.max(0, (sp('tweetPadTop') ?? 45) / 100) * fs; // card top edge -> avatar top
  const padBottom = Math.max(0, (sp('tweetPadBottom') ?? 45) / 100) * fs; // stats line -> card bottom edge
  const av = fs * 0.8;                // avatar diameter
  const gapHeaderText = fs * 0.35;    // avatar bottom -> first line top
  const gapTextStats = fs * 0.4;      // last line bottom -> stats line
  const statsH = fs * 0.32;           // stats line height
  const bodyH = Math.max(blockH, minBlockH);
  const cardW = Math.max(maxLw + padLeft + padRight, minW, sp('tweetCardW'));
  const cardX = cx - cardW / 2;
  const slack = Math.max(0, cardW - padLeft + padRight - maxLw) / 2;
  // The body block's position inside the card follows the alignment
  // buttons (Reza, 2026-11-22): right hugs the card's inner right
  // edge, left hugs the inner left edge, centre sits in the middle.
  // Justify keeps the old direction-based anchor (RTL under the logo
  // on the right, LTR on the left) and stretches the lines instead.
  // Note: the chrome (avatar/logo) still mirrors by text direction —
  // only the body text follows the alignment buttons.
  const blockShift = state.align === 'right' ? slack + (padLeft - padRight) / 2
    : state.align === 'left' ? -slack + (padLeft - padRight) / 2
    : state.align === 'justify' ? (rtl ? slack : -slack) + (padLeft - padRight) / 2
    : (padLeft - padRight) / 2;
  const textTop = h / 2 - bodyH / 2;
  const textBottom = h / 2 + bodyH / 2;
  let cardTop = textTop - gapHeaderText - padTop - av;
  let cardBottom = textBottom + gapTextStats + statsH + padBottom;
  // Height floor: the card is at least the set size; the extra space
  // splits evenly above and below so the text stays centred.
  const extraH = Math.max(0, sp('tweetCardH') - (cardBottom - cardTop));
  cardTop -= extraH / 2;
  cardBottom += extraH / 2;
  const avatarX = rtl ? cardX + padLeft + av / 2 : cardX + cardW - padRight - av / 2;
  const avatarY = cardTop + padTop + av / 2;
  // Name + handle, centred on the avatar: the gap between the two
  // lines is the old 0.38x size plus the adjustable «فاصله نام و آیدی»
  // (Reza, 2026-11-21: the two lines were touching — the default 10px
  // opens a visible gap; 0 is the old tight look).
  const nameGap = fs * 0.38 + sp('tweetNameGap');
  return {
    x: cardX, y: cardTop, w: cardW, h: cardBottom - cardTop, r: 36,
    padX, padLeft, padRight, av, avatarX, avatarY,
    nameX: rtl ? avatarX + av / 2 + 16 : avatarX - av / 2 - 16,
    nameY: avatarY - nameGap / 2,
    handleY: avatarY + nameGap / 2,
    logoSize: fs * 0.5,
    logoX: rtl ? cardX + cardW - padRight - fs * 0.25 : cardX + padLeft + fs * 0.25,
    logoY: avatarY,
    statsX: cardX + padLeft,
    statsY: textBottom + gapTextStats + statsH / 2,
    statsH,
    blockShift, rtl,
  };
}

// The X logo (Simple Icons path, 24x24 viewBox), drawn once at module
// load; a bold «X» letter is the fallback if Path2D is unavailable.
const X_LOGO_PATH = 'M18.901 1.153h3.68l-8.04 9.19L24 22.846h-7.406l-5.8-7.584-6.638 7.584H.474l8.6-9.83L0 1.154h7.594l5.243 6.932ZM17.61 20.644h2.039L6.486 3.24H4.298Z';
let xLogoPath = null;
try { xLogoPath = new Path2D(X_LOGO_PATH); } catch { xLogoPath = null; }

// Paint the tweet card chrome: rounded card, avatar, name + handle, the
// X logo, and the likes/replies footer. Everything is editable in the
// settings sheet (name, handle, counts, card colour, avatar); the values
// below are the FontStory defaults. The user's text itself is painted
// per line by STYLE_PAINT.tweet.
function paintTweetCard(l, fs) {
  const name = (sp('tweetName') || '').trim() || 'FontStory';
  let handle = (sp('tweetHandle') || '').trim() || '@fontstory';
  if (!handle.startsWith('@')) handle = '@' + handle;
  const likes = (sp('tweetLikes') || '').trim() || '4.1k';
  const replies = (sp('tweetReplies') || '').trim() || '18';
  const card = sp('tweetCard') || '#000000';
  ctx.save();
  // All chrome strings are Latin — force LTR, or the page's RTL
  // direction mirrors the handle («storyfont@» instead of «@storyfont»).
  // Restored by the save/restore below; the main text is untouched.
  ctx.direction = 'ltr';
  // Card (a hairline border keeps it visible on any background).
  roundRect(l.x, l.y, l.w, l.h, l.r);
  ctx.fillStyle = card;
  ctx.fill();
  ctx.strokeStyle = hexAlpha(contrastText(card), 0.15);
  ctx.lineWidth = 1.5;
  ctx.stroke();
  // Avatar: the FontStory logo by default (web/logo-avatar.webp), or
  // the user's own image when they picked one. Drawn cover-fit into
  // the circle; while the image is still loading, a gradient + «F»
  // stands in.
  ctx.save();
  ctx.beginPath();
  ctx.arc(l.avatarX, l.avatarY, l.av / 2, 0, Math.PI * 2);
  ctx.clip();
  if (tweetAvatarImg && tweetAvatarImg.complete && tweetAvatarImg.naturalWidth > 0) {
    const iw = tweetAvatarImg.naturalWidth, ih = tweetAvatarImg.naturalHeight;
    const s = Math.max(l.av / iw, l.av / ih);
    ctx.drawImage(tweetAvatarImg, l.avatarX - (iw * s) / 2, l.avatarY - (ih * s) / 2, iw * s, ih * s);
  } else {
    const g = ctx.createLinearGradient(l.avatarX - l.av / 2, l.avatarY - l.av / 2, l.avatarX + l.av / 2, l.avatarY + l.av / 2);
    g.addColorStop(0, '#F472B6');
    g.addColorStop(0.55, '#EC4899');
    g.addColorStop(1, '#BE185D');
    ctx.fillStyle = g;
    ctx.fillRect(l.avatarX - l.av / 2, l.avatarY - l.av / 2, l.av, l.av);
    ctx.fillStyle = '#FFFFFF';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = `800 ${l.av * 0.55}px 'Vazir', system-ui, sans-serif`;
    ctx.fillText('F', l.avatarX, l.avatarY);
  }
  ctx.restore();
  // Name + handle, next to the avatar: left-aligned for RTL (avatar
  // left), right-aligned for LTR (avatar right, nameX is the right edge).
  ctx.textAlign = l.rtl ? 'left' : 'right';
  ctx.fillStyle = '#FFFFFF';
  ctx.font = `700 ${fs * 0.42}px 'Vazir', system-ui, sans-serif`;
  ctx.fillText(name, l.nameX, l.nameY);
  ctx.fillStyle = '#71717A';
  ctx.font = `400 ${fs * 0.34}px 'Vazir', system-ui, sans-serif`;
  ctx.fillText(handle, l.nameX, l.handleY);
  // X logo, right side, centred on the avatar.
  ctx.fillStyle = '#FFFFFF';
  if (xLogoPath) {
    ctx.save();
    ctx.translate(l.logoX - l.logoSize / 2, l.logoY - l.logoSize / 2);
    ctx.scale(l.logoSize / 24, l.logoSize / 24);
    ctx.fill(xLogoPath);
    ctx.restore();
  } else {
    ctx.font = `800 ${l.logoSize}px 'Vazir', system-ui, sans-serif`;
    ctx.textAlign = 'center';
    ctx.fillText('X', l.logoX, l.logoY);
  }
  // Footer: likes + replies.
  ctx.textAlign = 'left';
  ctx.fillStyle = '#A1A1AA';
  ctx.font = `400 ${fs * 0.32}px 'Vazir', system-ui, sans-serif`;
  ctx.fillText(`${likes} likes  ${replies} replies`, l.statsX, l.statsY);
  ctx.restore();
}

// iPhone Notes frame (Reza, 2026-11-22): a white card with the gold
// Notes header and the text in the light-grey content area below.
// Colours sampled from his screenshot: gold #D9AA1E, text #595355.
// The content was dusty-pink #E4D0D9 until 2026-11-22, when Reza
// asked for the crimson tone removed — briefly white, then light
// grey #E5E5EA so the header band and the content are not the same
// colour (Reza: a bit darker). Like the
// tweet card, the chrome stays fixed
// at NOTE_CHROME_FS while the body text follows the side size rail.
const NOTE_CHROME_FS = 110;
const NOTE_GOLD = '#D9AA1E';

// Minimum size of the note card: at least as wide as its gold header
// row (chevron + Notes + ... + share + Done), measured at its own
// font size, and at least as tall as one body line.
function noteMinSize(fs) {
  const prevFont = ctx.font;
  ctx.font = `400 ${fs * 0.42}px 'Vazir', system-ui, sans-serif`;
  const notesW = ctx.measureText('Notes').width;
  const doneW = ctx.measureText('Done').width;
  ctx.font = prevFont;
  const padLeft = Math.max(0, sp('notePadLeft') ?? 56), padRight = Math.max(0, sp('notePadRight') ?? 56); // same as noteLayout
  // padX + chevron + gap + Notes + gap + dots circle + gap + share +
  // gap + Done + padX.
  const headerW = padLeft + padRight + fs * 0.28 + fs * 0.12 + notesW + fs * 0.28 + fs * 0.5 + fs * 0.28 + fs * 0.42 + fs * 0.28 + doneW;
  return { minW: headerW, minBlockH: fs * state.lineHeight };
}

// Geometry of the note card around the text block. The card's SIZE is
// adjustable (noteCardW/noteCardH, same defaults as the tweet card: a
// 760x480 floor the content can grow past). The body block's position
// follows the alignment buttons, same rule as the tweet card: right
// hugs the inner right edge, left the inner left edge, centre sits in
// the middle; justify keeps the direction-based anchor.
function noteLayout(fs, maxLw, blockH, lineHeight, h, cx, minW = 0, minBlockH = 0, rtl = true) {
  // Side padding: two knobs (2026-11-24), defaults = the old symmetric
  // padding; padX stays as their average for the symmetric chrome.
  const padLeft = Math.max(0, sp('notePadLeft') ?? 56);
  const padRight = Math.max(0, sp('notePadRight') ?? 56);
  const padX = (padLeft + padRight) / 2;
  const headerH = fs * 1.1;           // white header band height (Reza, 2026-11-22: a bit taller)
  const gapHeaderText = Math.max(0, (sp('notePadTop') ?? 35) / 100) * fs; // header bottom -> first line top (top knob)
  const padBottom = Math.max(0, (sp('notePadBottom') ?? 45) / 100) * fs; // last line bottom -> card bottom
  const bodyH = Math.max(blockH, minBlockH);
  const cardW = Math.max(maxLw + padLeft + padRight, minW, sp('noteCardW'));
  const cardX = cx - cardW / 2;
  const slack = Math.max(0, cardW - padLeft + padRight - maxLw) / 2;
  const blockShift = state.align === 'right' ? slack + (padLeft - padRight) / 2
    : state.align === 'left' ? -slack + (padLeft - padRight) / 2
    : state.align === 'justify' ? (rtl ? slack : -slack) + (padLeft - padRight) / 2
    : (padLeft - padRight) / 2;
  const textTop = h / 2 - bodyH / 2;
  const textBottom = h / 2 + bodyH / 2;
  let cardTop = textTop - gapHeaderText - headerH;
  let cardBottom = textBottom + padBottom;
  // Height floor: the card is at least the set size; the extra space
  // splits evenly above and below so the text stays centred.
  const extraH = Math.max(0, sp('noteCardH') - (cardBottom - cardTop));
  cardTop -= extraH / 2;
  cardBottom += extraH / 2;
  return {
    x: cardX, y: cardTop, w: cardW, h: cardBottom - cardTop, r: 36,
    padX, padLeft, padRight, headerH, blockShift, rtl,
  };
}

// Paint the note card chrome: light-grey card with a white header band
// and the gold iOS Notes header (‹ Notes on the left, ... / share /
// Done on the right, LTR like the screenshot). The user's text itself
// is painted per line by STYLE_PAINT.note.
function paintNoteCard(l, fs) {
  const content = sp('noteC') || '#E5E5EA';
  ctx.save();
  // Card body (pink) + white header band (clipped to the rounded top).
  roundRect(l.x, l.y, l.w, l.h, l.r);
  ctx.fillStyle = content;
  ctx.fill();
  ctx.save();
  roundRect(l.x, l.y, l.w, l.h, l.r);
  ctx.clip();
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(l.x, l.y, l.w, l.headerH);
  ctx.restore();
  // Gold header, LTR.
  ctx.fillStyle = NOTE_GOLD;
  ctx.strokeStyle = NOTE_GOLD;
  ctx.textBaseline = 'middle';
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  const hy = l.y + l.headerH / 2;
  const headFont = `400 ${fs * 0.42}px 'Vazir', system-ui, sans-serif`;
  ctx.font = headFont;
  // Chevron «‹» + Notes, left.
  const chevX = l.x + l.padLeft, chevS = fs * 0.28;
  ctx.lineWidth = fs * 0.045;
  ctx.beginPath();
  ctx.moveTo(chevX + chevS * 0.7, hy - chevS / 2);
  ctx.lineTo(chevX, hy);
  ctx.lineTo(chevX + chevS * 0.7, hy + chevS / 2);
  ctx.stroke();
  ctx.textAlign = 'left';
  ctx.fillText('Notes', chevX + chevS + fs * 0.12, hy);
  // Done, right.
  ctx.textAlign = 'right';
  ctx.fillText('Done', l.x + l.w - l.padRight, hy);
  const doneW = ctx.measureText('Done').width;
  // Share icon (a U-shaped box with an up arrow), left of Done.
  const shS = fs * 0.42;
  const shRight = l.x + l.w - l.padRight - doneW - fs * 0.28;
  const shX = shRight - shS, shCy = hy;
  ctx.lineWidth = fs * 0.035;
  ctx.beginPath();
  ctx.moveTo(shX, shCy - shS * 0.1);
  ctx.lineTo(shX, shCy + shS * 0.35);
  ctx.lineTo(shX + shS, shCy + shS * 0.35);
  ctx.lineTo(shX + shS, shCy - shS * 0.1);
  ctx.moveTo(shX + shS / 2, shCy + shS * 0.15);
  ctx.lineTo(shX + shS / 2, shCy - shS * 0.45);
  ctx.moveTo(shX + shS / 2 - shS * 0.18, shCy - shS * 0.25);
  ctx.lineTo(shX + shS / 2, shCy - shS * 0.45);
  ctx.lineTo(shX + shS / 2 + shS * 0.18, shCy - shS * 0.25);
  ctx.stroke();
  // «...» in a circle, left of the share icon.
  const dotR = fs * 0.25;
  const dotCx = shX - fs * 0.28 - dotR;
  ctx.lineWidth = fs * 0.03;
  ctx.beginPath();
  ctx.arc(dotCx, hy, dotR, 0, Math.PI * 2);
  ctx.stroke();
  ctx.beginPath();
  for (const dx of [-fs * 0.09, 0, fs * 0.09]) {
    ctx.moveTo(dotCx + dx + fs * 0.03, hy);
    ctx.arc(dotCx + dx, hy, fs * 0.03, 0, Math.PI * 2);
  }
  ctx.fill();
  ctx.restore();
}

// at MESSAGE_CHROME_FS while the body text follows the side size rail.
const MESSAGE_CHROME_FS = 110;
const MESSAGE_GREY = '#8B8B8D';

// Minimum size of the message card: at least as wide as its header
// row (Messages icon + Messages + Now), measured at its own font
// size, and at least as tall as one body line.
function messageMinSize(fs) {
  const prevFont = ctx.font;
  ctx.font = `400 ${fs * 0.42}px 'Vazir', system-ui, sans-serif`;
  const messagesW = ctx.measureText('Messages').width;
  const nowW = ctx.measureText('Now').width;
  ctx.font = prevFont;
  const padLeft = Math.max(0, sp('messagePadLeft') ?? 56), padRight = Math.max(0, sp('messagePadRight') ?? 56); // same as messageLayout
  // padX + icon + gap + Messages + gap + Now + padX.
  const headerW = padLeft + padRight + fs * 0.68 + fs * 0.12 + messagesW + fs * 0.28 + nowW;
  return { minW: headerW, minBlockH: fs * state.lineHeight };
}

// Geometry of the message card around the text block. The card's SIZE
// is adjustable (messageCardW/messageCardH, same defaults as the
// tweet/note cards: a 760x480 floor the content can grow past). The
// body block's position follows the alignment buttons, same rule as
// the tweet/note cards: right hugs the inner right edge, left the
// inner left edge, centre sits in the middle; justify keeps the
// direction-based anchor.
function messageLayout(fs, maxLw, blockH, lineHeight, h, cx, minW = 0, minBlockH = 0, rtl = true) {
  // Side padding: two knobs (2026-11-24), defaults = the old symmetric
  // padding; padX stays as their average for the symmetric chrome.
  const padLeft = Math.max(0, sp('messagePadLeft') ?? 56);
  const padRight = Math.max(0, sp('messagePadRight') ?? 56);
  const padX = (padLeft + padRight) / 2;
  const headerH = fs * 1.1;           // white header band height
  const gapHeaderText = Math.max(0, (sp('messagePadTop') ?? 35) / 100) * fs; // header bottom -> first line top (top knob)
  const padBottom = Math.max(0, (sp('messagePadBottom') ?? 45) / 100) * fs; // last line bottom -> card bottom
  const bodyH = Math.max(blockH, minBlockH);
  const cardW = Math.max(maxLw + padLeft + padRight, minW, sp('messageCardW'));
  const cardX = cx - cardW / 2;
  const slack = Math.max(0, cardW - padLeft + padRight - maxLw) / 2;
  const blockShift = state.align === 'right' ? slack + (padLeft - padRight) / 2
    : state.align === 'left' ? -slack + (padLeft - padRight) / 2
    : state.align === 'justify' ? (rtl ? slack : -slack) + (padLeft - padRight) / 2
    : (padLeft - padRight) / 2;
  const textTop = h / 2 - bodyH / 2;
  const textBottom = h / 2 + bodyH / 2;
  let cardTop = textTop - gapHeaderText - headerH;
  let cardBottom = textBottom + padBottom;
  // Height floor: the card is at least the set size; the extra space
  // splits evenly above and below so the text stays centred.
  const extraH = Math.max(0, sp('messageCardH') - (cardBottom - cardTop));
  cardTop -= extraH / 2;
  cardBottom += extraH / 2;
  return {
    x: cardX, y: cardTop, w: cardW, h: cardBottom - cardTop, r: 36,
    padX, padLeft, padRight, headerH, blockShift, rtl,
  };
}

// Paint the message card chrome: light-grey card with a white header
// band and the iOS Messages header (green app icon + Messages on the
// left, Now on the right, LTR like the screenshot). The user's text
// itself is painted per line by STYLE_PAINT.message.
function paintMessageCard(l, fs) {
  const content = sp('messageC') || '#E5E5EA';
  ctx.save();
  // Card body (pink) + white header band (clipped to the rounded top).
  roundRect(l.x, l.y, l.w, l.h, l.r);
  ctx.fillStyle = content;
  ctx.fill();
  ctx.save();
  roundRect(l.x, l.y, l.w, l.h, l.r);
  ctx.clip();
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(l.x, l.y, l.w, l.headerH);
  ctx.restore();
  // Grey header, LTR.
  ctx.textBaseline = 'middle';
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  const hy = l.y + l.headerH / 2;
  const headFont = `400 ${fs * 0.42}px 'Vazir', system-ui, sans-serif`;
  ctx.font = headFont;
  // Green Messages app icon, left (vertical gradient like the real
  // icon: bright lime at the top, deeper green at the bottom).
  const iconS = fs * 0.68;
  const iconX = l.x + l.padLeft, iconY = hy - iconS / 2;
  const iconGrad = ctx.createLinearGradient(iconX, iconY, iconX, iconY + iconS);
  iconGrad.addColorStop(0, '#8BD94F');
  iconGrad.addColorStop(1, '#3ABA29');
  roundRect(iconX, iconY, iconS, iconS, iconS * 0.22);
  ctx.fillStyle = iconGrad;
  ctx.fill();
  // White speech bubble inside the icon: an ellipse with a tail at
  // the bottom-left.
  const bx = iconX + iconS / 2, by = iconY + iconS * 0.47;
  const bw = iconS * 0.32, bh = iconS * 0.24;
  ctx.fillStyle = '#FFFFFF';
  ctx.beginPath();
  ctx.ellipse(bx, by, bw, bh, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(bx - bw * 0.55, by + bh * 0.55);
  ctx.lineTo(bx - bw * 0.15, by + bh * 0.55);
  ctx.lineTo(bx - bw * 0.75, by + bh * 1.15);
  ctx.closePath();
  ctx.fill();
  // «Messages», left of the icon.
  ctx.fillStyle = MESSAGE_GREY;
  ctx.textAlign = 'left';
  ctx.fillText('Messages', iconX + iconS + fs * 0.12, hy);
  // «Now», right.
  ctx.textAlign = 'right';
  ctx.fillText('Now', l.x + l.w - l.padRight, hy);
  ctx.restore();
}

// Geometry of the pinned note card around the text block (Reza,
// 2026-11-23 — his createPinnedNoteCard code). The card's SIZE is
// adjustable (pinCardW/pinCardH, same defaults as the note/message
// cards: a 760x480 floor the content can grow past). The top padding
// leaves room for the pushpin at the top-right corner; the body
// block's position follows the alignment buttons, same rule as the
// note card: right hugs the inner right edge, left the inner left
// edge, centre sits in the middle; justify keeps the direction-based
// anchor.
function pinLayout(fs, maxLw, blockH, lineHeight, h, cx, rtl = true) {
  // Side padding: two knobs (2026-11-24), defaults = the old symmetric
  // padding; padX stays as their average for the symmetric chrome.
  const padLeft = Math.max(0, sp('pinPadLeft') ?? 56);
  const padRight = Math.max(0, sp('pinPadRight') ?? 56);
  const padX = (padLeft + padRight) / 2;
  const padTop = Math.max(0, (sp('pinPadTop') ?? 90) / 100) * fs; // room for the pin at the top-right
  const padBottom = Math.max(0, (sp('pinPadBottom') ?? 40) / 100) * fs; // last line bottom -> card bottom
  const bodyH = blockH;
  const cardW = Math.max(maxLw + padLeft + padRight, sp('pinCardW'));
  const cardX = cx - cardW / 2;
  const slack = Math.max(0, cardW - padLeft + padRight - maxLw) / 2;
  const blockShift = state.align === 'right' ? slack + (padLeft - padRight) / 2
    : state.align === 'left' ? -slack + (padLeft - padRight) / 2
    : state.align === 'justify' ? (rtl ? slack : -slack) + (padLeft - padRight) / 2
    : (padLeft - padRight) / 2;
  const textTop = h / 2 - bodyH / 2;
  const textBottom = h / 2 + bodyH / 2;
  let cardTop = textTop - padTop;
  let cardBottom = textBottom + padBottom;
  // Height floor: the card is at least the set size; the extra space
  // splits evenly above and below so the text stays centred.
  const extraH = Math.max(0, sp('pinCardH') - (cardBottom - cardTop));
  cardTop -= extraH / 2;
  cardBottom += extraH / 2;
  return {
    x: cardX, y: cardTop, w: cardW, h: cardBottom - cardTop, r: 36,
    padX, padLeft, padRight, padTop, padBottom, blockShift, rtl,
  };
}

// Paint the pinned note card: a rounded card with his soft shadow
// (0 14px 34px rgba(70, 8, 22, 0.16)) and the realistic 3D pushpin
// at the top-right corner (his: top 14px, right 18px, size 108px at a
// 680px card — all scaled by the card width). The text itself is
// painted per line by STYLE_PAINT.pin, on top of the pin.
function paintPinCard(l, fs) {
  const u = l.w / 680; // his reference card width
  ctx.save();
  ctx.shadowColor = 'rgba(70, 8, 22, 0.16)';
  ctx.shadowBlur = 34 * u;
  ctx.shadowOffsetY = 14 * u;
  roundRect(l.x, l.y, l.w, l.h, l.r);
  ctx.fillStyle = sp('pinCardC') || '#FFFFFF';
  ctx.fill();
  ctx.restore();
  const img = getPinImage(sp('pinC') || '#df1217');
  const pinSize = l.w * 0.16;
  const pinX = l.x + l.w - 0.026 * l.w - pinSize;
  const pinY = l.y + 0.021 * l.w;
  if (img.complete && img.naturalWidth > 0) {
    ctx.drawImage(img, pinX, pinY, pinSize, pinSize);
  }
  // (No flat fallback — the pin is too detailed to fake with paths;
  // the data: URL loads immediately and onload redraws.)
}

// --- Music player card (Reza, 2026-11-23 — his createMusicPlayerCard
// code): a dark glass card with a subtitle, the title, a progress bar
// with times, play controls, and a volume row. The icons are his SVG
// paths, drawn with Path2D (same technique as the bubble tails).
const MUSIC_REWIND_TRI = 'M21.2 4.6c1.2-.8 2.8.1 2.8 1.5v15.8c0 1.4-1.6 2.3-2.8 1.5L7.8 15.5c-1.1-.7-1.1-2.3 0-3l13.4-7.9z';
const MUSIC_FORWARD_TRI = 'M22.8 4.6c-1.2-.8-2.8.1-2.8 1.5v15.8c0 1.4 1.6 2.3 2.8 1.5l13.4-7.9c1.1-.7 1.1-2.3 0-3L22.8 4.6z';
const MUSIC_VOL_LOW_SPEAKER = 'M2.6 8.5h4.2l5.4-4.6c.8-.7 2-.1 2 1v14.2c0 1.1-1.2 1.7-2 1l-5.4-4.6H2.6c-.9 0-1.6-.7-1.6-1.6v-3.8c0-.9.7-1.6 1.6-1.6z';
const MUSIC_VOL_LOW_ARC = 'M18.2 8.8c1.4 1.8 1.4 4.6 0 6.4';
const MUSIC_VOL_HIGH_SPEAKER = 'M2.2 9.5h4.0l5.1-4.3c.8-.6 1.9-.1 1.9.9v13.8c0 1-1.1 1.5-1.9.9l-5.1-4.3H2.2c-.8 0-1.5-.7-1.5-1.5v-4c0-.8.7-1.5 1.5-1.5z';
const MUSIC_VOL_HIGH_ARCS = ['M16.8 9.8c1.3 1.7 1.3 4.7 0 6.4', 'M20.4 7.0c2.5 3.3 2.5 8.7 0 12.0', 'M24.2 4.3c3.8 5.0 3.8 12.4 0 17.4'];
// Set up the transform so his viewBox (vbW x vbH) fits a `size` box
// centred at (cx, cy) — the SVG "meet" fit: scale by the constraining
// side, centred on the other. The caller draws in viewBox units and
// restores.
function musicIconTransform(vbW, vbH, cx, cy, size) {
  const s = Math.min(size / vbW, size / vbH);
  const w = vbW * s, h = vbH * s;
  ctx.save();
  ctx.translate(cx - w / 2, cy - h / 2);
  ctx.scale(s, s);
}
function paintMusicRewind(cx, cy, size, ink) {
  musicIconTransform(44, 28, cx, cy, size);
  ctx.fillStyle = ink;
  ctx.save(); ctx.translate(17, 0); ctx.fill(new Path2D(MUSIC_REWIND_TRI)); ctx.restore();
  ctx.save(); ctx.translate(-3.5, 0); ctx.fill(new Path2D(MUSIC_REWIND_TRI)); ctx.restore();
  ctx.restore();
}
function paintMusicForward(cx, cy, size, ink) {
  musicIconTransform(44, 28, cx, cy, size);
  ctx.fillStyle = ink;
  ctx.save(); ctx.translate(-17, 0); ctx.fill(new Path2D(MUSIC_FORWARD_TRI)); ctx.restore();
  ctx.save(); ctx.translate(3.5, 0); ctx.fill(new Path2D(MUSIC_FORWARD_TRI)); ctx.restore();
  ctx.restore();
}
function paintMusicPause(cx, cy, size, ink) {
  musicIconTransform(32, 36, cx, cy, size);
  ctx.fillStyle = ink;
  roundRect(4, 3, 9.2, 30, 2.6); ctx.fill();
  roundRect(18.8, 3, 9.2, 30, 2.6); ctx.fill();
  ctx.restore();
}
function paintMusicVolLow(cx, cy, size, ink) {
  musicIconTransform(28, 24, cx, cy, size);
  ctx.fillStyle = ink;
  ctx.fill(new Path2D(MUSIC_VOL_LOW_SPEAKER));
  ctx.strokeStyle = ink;
  ctx.lineWidth = 2;
  ctx.lineCap = 'round';
  ctx.stroke(new Path2D(MUSIC_VOL_LOW_ARC));
  ctx.restore();
}
function paintMusicVolHigh(cx, cy, size, ink) {
  musicIconTransform(34, 26, cx, cy, size);
  ctx.fillStyle = ink;
  ctx.fill(new Path2D(MUSIC_VOL_HIGH_SPEAKER));
  ctx.strokeStyle = ink;
  ctx.lineWidth = 1.9;
  ctx.lineCap = 'round';
  for (const d of MUSIC_VOL_HIGH_ARCS) ctx.stroke(new Path2D(d));
  ctx.restore();
}
// His hexToRgba (card colour + opacity -> rgba string), reusing the
// pin's hexToRgb.
function hexToRgba(hex, alpha) {
  const [r, g, b] = hexToRgb(hex);
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}
// The chrome ink (subtitle, progress, controls, volume): the رنگ tab
// wins once a colour is picked (flat — a gradient's first stop, since
// the chrome is painted with fillStyle, not drawWords); otherwise the
// text stays readable on the card colour via contrastText.
function musicInk() {
  if (state.colorTouched) return flatColor(state.color);
  return contrastText(sp('musicCardC') || '#1a040d');
}

// Geometry of the music player card around the text block (Reza,
// 2026-11-23 — his createMusicPlayerCard code). The card's SIZE is
// adjustable (musicCardW/musicCardH, same defaults as the note/message
// cards: a 760x480 floor the content can grow past). The subtitle sits
// above the title and the progress / controls / volume rows below it;
// the body block's position follows the alignment buttons, same rule
// as the note card. The section centres are anchored to the text
// block, so they never move when the height floor adds space.
function musicLayout(fs, maxLw, blockH, lineHeight, h, cx, rtl = true) {
  // Side padding: two knobs (2026-11-24), defaults = the old symmetric
  // padding; padX stays as their average for the symmetric chrome.
  const padLeft = Math.max(0, sp('musicPadLeft') ?? 56);
  const padRight = Math.max(0, sp('musicPadRight') ?? 56);
  const padX = (padLeft + padRight) / 2;
  const subtitleFs = fs * 0.15;       // «Music by Font Story», his ~16px
  const gapSubtitleText = fs * 0.3;   // subtitle -> title
  const gapTextProgress = fs * 0.35;  // title -> progress bar
  const trackH = fs * 0.045;          // progress track height, his 5px
  const timeFs = fs * 0.14;           // time labels, his ~15px
  const gapTrackTime = fs * 0.055;    // track -> time row
  const gapProgressControls = fs * 0.18; // time row -> controls
  const controlsH = fs * 0.5;         // controls row, his ~54px rewind
  const gapControlsVolume = fs * 0.3; // controls -> volume row
  const volumeH = fs * 0.29;          // volume row, his ~32px high icon
  const padTop = Math.max(0, (sp('musicPadTop') ?? 24) / 100) * fs; // card top -> subtitle
  const padBottom = Math.max(0, (sp('musicPadBottom') ?? 25) / 100) * fs; // volume row -> card bottom
  const bodyH = blockH;
  const cardW = Math.max(maxLw + padLeft + padRight, sp('musicCardW'));
  const cardX = cx - cardW / 2;
  const slack = Math.max(0, cardW - padLeft + padRight - maxLw) / 2;
  const blockShift = state.align === 'right' ? slack + (padLeft - padRight) / 2
    : state.align === 'left' ? -slack + (padLeft - padRight) / 2
    : state.align === 'justify' ? (rtl ? slack : -slack) + (padLeft - padRight) / 2
    : (padLeft - padRight) / 2;
  const textTop = h / 2 - bodyH / 2;
  const textBottom = h / 2 + bodyH / 2;
  const subtitleY = textTop - gapSubtitleText - subtitleFs / 2;
  const progressTrackY = textBottom + gapTextProgress + trackH / 2;
  const timeY = progressTrackY + trackH / 2 + gapTrackTime + timeFs / 2;
  const controlsY = timeY + timeFs / 2 + gapProgressControls + controlsH / 2;
  const volumeY = controlsY + controlsH / 2 + gapControlsVolume + volumeH / 2;
  let cardTop = textTop - gapSubtitleText - subtitleFs - padTop;
  let cardBottom = volumeY + volumeH / 2 + padBottom;
  // Height floor: the card is at least the set size; the extra space
  // splits evenly above and below so the text stays centred.
  const extraH = Math.max(0, sp('musicCardH') - (cardBottom - cardTop));
  cardTop -= extraH / 2;
  cardBottom += extraH / 2;
  return {
    x: cardX, y: cardTop, w: cardW, h: cardBottom - cardTop, r: 40,
    padX, padLeft, padRight, blockShift, rtl,
    subtitleFs, subtitleY, progressTrackY, trackH, timeFs, timeY,
    controlsY, controlsH, volumeY, volumeH,
  };
}

// Paint the music player card: the dark glass card (his cardColor at
// cardOpacity — the backdrop blur is skipped: the page backgrounds are
// smooth gradients, so a blur would change almost nothing, and the
// tint alone reads as glass), then the subtitle, the progress bar with
// its times, the play controls, and the volume row. The title itself
// is painted per line by STYLE_PAINT.music.
function paintMusicCard(l, fs) {
  const ink = musicInk();
  const cardC = sp('musicCardC') || '#1a040d';
  const cardO = (sp('musicCardO') || 48) / 100;
  ctx.save();
  roundRect(l.x, l.y, l.w, l.h, l.r);
  ctx.fillStyle = hexToRgba(cardC, cardO);
  ctx.fill();
  ctx.restore();
  // Subtitle (top, centred, latin, white at 0.72 opacity).
  ctx.save();
  ctx.fillStyle = ink;
  ctx.globalAlpha = 0.72;
  ctx.font = `400 ${l.subtitleFs}px 'Vazir', system-ui, sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText((sp('musicSubtitle') || '').trim() || 'Music by Font Story', l.x + l.w / 2, l.subtitleY);
  ctx.restore();
  // Progress: a white track at 0.42 opacity, a white fill to the
  // progress %, and a white knob with a soft shadow at its end.
  const progX0 = l.x + l.padLeft, progX1 = l.x + l.w - l.padRight;
  const progW = progX1 - progX0;
  const prog = Math.max(0, Math.min(100, sp('musicProgress') ?? 61)) / 100;
  ctx.save();
  ctx.fillStyle = ink;
  ctx.globalAlpha = 0.42;
  roundRect(progX0, l.progressTrackY - l.trackH / 2, progW, l.trackH, l.trackH / 2);
  ctx.fill();
  ctx.restore();
  ctx.save();
  ctx.fillStyle = ink;
  roundRect(progX0, l.progressTrackY - l.trackH / 2, progW * prog, l.trackH, l.trackH / 2);
  ctx.fill();
  ctx.restore();
  const knobX = progX0 + progW * prog;
  const knobR = l.trackH * 1.5;
  ctx.save();
  ctx.shadowColor = 'rgba(0, 0, 0, 0.25)';
  ctx.shadowBlur = 4;
  ctx.shadowOffsetY = 1;
  ctx.fillStyle = ink;
  ctx.beginPath();
  ctx.arc(knobX, l.progressTrackY, knobR, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
  // Times: current (left) and total (right), latin, white at 0.88.
  ctx.save();
  ctx.fillStyle = ink;
  ctx.globalAlpha = 0.88;
  ctx.font = `400 ${l.timeFs}px 'Vazir', system-ui, sans-serif`;
  ctx.textBaseline = 'middle';
  ctx.textAlign = 'left';
  ctx.fillText((sp('musicCurrent') || '').trim() || '2:00', progX0, l.timeY);
  ctx.textAlign = 'right';
  ctx.fillText((sp('musicTotal') || '').trim() || '2:52', progX1, l.timeY);
  ctx.restore();
  // Controls: rewind, pause, forward — white icons, centred on the card.
  const gap = fs * 0.37;
  const rwSize = fs * 0.5;
  const ppSize = fs * 0.42;
  const ppW = ppSize * (32 / 36); // pause viewBox is 32x36 (taller than wide)
  const totalW = rwSize + gap + ppW + gap + rwSize;
  let cx = l.x + l.w / 2 - totalW / 2;
  paintMusicRewind(cx + rwSize / 2, l.controlsY, rwSize, ink);
  cx += rwSize + gap;
  paintMusicPause(cx + ppW / 2, l.controlsY, ppSize, ink);
  cx += ppW + gap;
  paintMusicForward(cx + rwSize / 2, l.controlsY, rwSize, ink);
  // Volume: low icon, a solid white track with a knob at the volume %,
  // high icon.
  const volGap = fs * 0.13;
  const volLowSize = fs * 0.23, volHighSize = fs * 0.26;
  const volTrackH = fs * 0.05;
  const volKnobR = fs * 0.1;
  const vol = Math.max(0, Math.min(100, sp('musicVolume') ?? 20)) / 100;
  const trackX0 = l.x + l.padLeft + volLowSize + volGap;
  const trackX1 = l.x + l.w - l.padRight - volHighSize - volGap;
  const trackW = trackX1 - trackX0;
  paintMusicVolLow(l.x + l.padLeft + volLowSize / 2, l.volumeY, volLowSize, ink);
  paintMusicVolHigh(l.x + l.w - l.padRight - volHighSize / 2, l.volumeY, volHighSize, ink);
  ctx.save();
  ctx.fillStyle = ink;
  roundRect(trackX0, l.volumeY - volTrackH / 2, trackW, volTrackH, volTrackH / 2);
  ctx.fill();
  ctx.restore();
  ctx.save();
  ctx.shadowColor = 'rgba(0, 0, 0, 0.25)';
  ctx.shadowBlur = 6;
  ctx.shadowOffsetY = 2;
  ctx.fillStyle = ink;
  ctx.beginPath();
  ctx.arc(trackX0 + trackW * vol, l.volumeY, volKnobR, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

// --- Pink frame text card (Reza, 2026-11-23 — his createPinkFrameTextCard
// code): a white card with sharp corners and a thick pink border around
// the text. The border width is a knob (his 26px); the card padding is
// his fixed 48px vertical / 56px horizontal (not fs units — it is a
// card design value, like the note's 56px side padding).
function frameLayout(fs, maxLw, blockH, lineHeight, h, cx, rtl = true) {
  // Side padding: two knobs (2026-11-24), defaults = the old symmetric
  // padding; padX stays as their average for the symmetric chrome.
  const padLeft = Math.max(0, sp('framePadLeft') ?? 56);
  const padRight = Math.max(0, sp('framePadRight') ?? 56);
  const padX = (padLeft + padRight) / 2;
  const padTop = Math.max(0, sp('framePadTop') ?? 48), padBottom = Math.max(0, sp('framePadBottom') ?? 48);
  const bw = sp('frameBorder') ?? 26;
  const bodyH = blockH;
  const cardW = Math.max(maxLw + padLeft + padRight + bw * 2, sp('frameCardW'));
  const cardX = cx - cardW / 2;
  const slack = Math.max(0, cardW - padLeft + padRight + bw * 2 - maxLw) / 2;
  const blockShift = state.align === 'right' ? slack + (padLeft - padRight) / 2
    : state.align === 'left' ? -slack + (padLeft - padRight) / 2
    : state.align === 'justify' ? (rtl ? slack : -slack) + (padLeft - padRight) / 2
    : (padLeft - padRight) / 2;
  const textTop = h / 2 - bodyH / 2;
  const textBottom = h / 2 + bodyH / 2;
  let cardTop = textTop - padTop - bw;
  let cardBottom = textBottom + padBottom + bw;
  // Height floor: the card is at least the set size; the extra space
  // splits evenly above and below so the text stays centred.
  const extraH = Math.max(0, sp('frameCardH') - (cardBottom - cardTop));
  cardTop -= extraH / 2;
  cardBottom += extraH / 2;
  return {
    x: cardX, y: cardTop, w: cardW, h: cardBottom - cardTop, r: 0,
    padX, padLeft, padRight, bw, blockShift, rtl,
  };
}

// Paint the pink frame card: the outer rect in the accent colour (the
// border), the inner rect in the card colour. Sharp corners, radius 0
// — his design.
function paintFrameCard(l) {
  const accent = sp('frameAccent') || '#ff96aa';
  const cardC = sp('frameCardC') || '#FFFFFF';
  ctx.save();
  ctx.fillStyle = accent;
  ctx.fillRect(l.x, l.y, l.w, l.h);
  ctx.fillStyle = cardC;
  ctx.fillRect(l.x + l.bw, l.y + l.bw, l.w - 2 * l.bw, l.h - 2 * l.bw);
  ctx.restore();
}

// --- Bell note card (Reza, 2026-11-23 — his createBellNoteCard code):
// a dark slate glass card with a bell badge sticking out of the
// top-left corner and a hand-drawn line near the bottom. The badge is
// his SVG, drawn with Path2D in a 200x200 viewBox (same technique as
// the music icons).
const BELL_INNER_CIRCLE = 'M 102 18 C 148 17, 182 51, 182 99 C 182 146, 146 182, 98 181 C 51 180, 18 147, 19 100 C 20 52, 54 19, 102 18 Z';
const BELL_KNOB = 'M 91 55 C 90 47, 94 42, 100 42 C 106 42, 110 47, 109 55 C 105 54, 95 54, 91 55 Z';
const BELL_BODY = 'M 100 59 C 118 59, 128 72, 131 94 C 134 111, 138 119, 146 125 C 149 128, 147 134, 141 136 C 126 141, 74 141, 59 136 C 53 134, 51 128, 54 125 C 62 119, 66 111, 69 94 C 72 72, 82 59, 100 59 Z';
const BELL_HEART = 'M 100 121 C 96 118, 78 105, 78 92 C 78 84, 85 80, 92 82 C 96 83, 99 87, 100 90 C 101 87, 104 83, 108 82 C 115 80, 122 84, 122 92 C 122 105, 104 118, 100 121 Z';
const BELL_CLAPPER = 'M 89 144 C 94 145, 106 145, 111 144 C 112 152, 107 157, 100 157 C 93 157, 88 152, 89 144 Z';
const BELL_LINE = 'M 4 10 C 74 6.5, 152 7.4, 232 8.4 C 306 9.2, 368 8.8, 416 7.4';
// Draw the bell badge in a d x d box centred at (cx, cy). The outer
// ring is the translucent card bg (darker where it overlaps the card,
// like his SVG); the inner circle and the heart are the badge colour;
// the knob, body and clapper are the bell colour. Draw order matches
// his SVG append order.
function paintBellBadge(cx, cy, d, cardBg, badgeBg, bellC) {
  const s = d / 200;
  ctx.save();
  ctx.translate(cx - d / 2, cy - d / 2);
  ctx.scale(s, s);
  ctx.fillStyle = cardBg;
  ctx.beginPath();
  ctx.arc(100, 100, 96, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = badgeBg;
  ctx.fill(new Path2D(BELL_INNER_CIRCLE));
  ctx.fillStyle = bellC;
  ctx.fill(new Path2D(BELL_KNOB));
  ctx.fill(new Path2D(BELL_BODY));
  ctx.fillStyle = badgeBg;
  ctx.fill(new Path2D(BELL_HEART));
  ctx.fillStyle = bellC;
  ctx.fill(new Path2D(BELL_CLAPPER));
  ctx.restore();
}
// Draw the hand-drawn line near the bottom of the card. His SVG uses
// preserveAspectRatio="none", so the 420x16 viewBox is stretched
// non-uniformly into the line's box — the canvas scale does the same,
// and the 3.5px stroke distorts the same way.
function paintBellLine(l, fs) {
  const lineC = sp('bellLineC') || '#b4bac6';
  const lineW = l.w * 0.71;
  const lineH = fs * 0.11;
  const lineX = l.x + l.w * 0.165;
  const lineTop = l.y + l.h - l.h * 0.082 - lineH;
  ctx.save();
  ctx.translate(lineX, lineTop);
  ctx.scale(lineW / 420, lineH / 16);
  ctx.strokeStyle = lineC;
  ctx.lineWidth = 3.5;
  ctx.lineCap = 'round';
  ctx.stroke(new Path2D(BELL_LINE));
  ctx.restore();
}

// Geometry of the bell note card around the text block (Reza,
// 2026-11-23 — his createBellNoteCard code). The card padding is his
// fixed max values (64px top, 68px bottom, 48px sides — card design
// values, not fs units, like the frame card). The badge overhangs the
// top-left corner: 24.8% of the card width wide, its left edge 8.2% of
// the card width left of the card, its top edge 12.2% of the card
// height above the card. The body block's position follows the
// alignment buttons, same rule as the note card.
function bellLayout(fs, maxLw, blockH, lineHeight, h, cx, rtl = true) {
  // Side padding: two knobs (2026-11-24), defaults = the old symmetric
  // padding; padX stays as their average for the symmetric chrome.
  const padLeft = Math.max(0, sp('bellPadLeft') ?? 48);
  const padRight = Math.max(0, sp('bellPadRight') ?? 48);
  const padX = (padLeft + padRight) / 2;
  const padTop = Math.max(0, sp('bellPadTop') ?? 64), padBottom = Math.max(0, sp('bellPadBottom') ?? 68);
  const bodyH = blockH;
  const cardW = Math.max(maxLw + padLeft + padRight, sp('bellCardW'));
  const cardX = cx - cardW / 2;
  const slack = Math.max(0, cardW - padLeft + padRight - maxLw) / 2;
  const blockShift = state.align === 'right' ? slack + (padLeft - padRight) / 2
    : state.align === 'left' ? -slack + (padLeft - padRight) / 2
    : state.align === 'justify' ? (rtl ? slack : -slack) + (padLeft - padRight) / 2
    : (padLeft - padRight) / 2;
  const textTop = h / 2 - bodyH / 2;
  const textBottom = h / 2 + bodyH / 2;
  let cardTop = textTop - padTop;
  let cardBottom = textBottom + padBottom;
  // Height floor: the card is at least the set size; the extra space
  // splits evenly above and below so the text stays centred.
  const extraH = Math.max(0, sp('bellCardH') - (cardBottom - cardTop));
  cardTop -= extraH / 2;
  cardBottom += extraH / 2;
  const r = Math.min(44, cardW * 0.06);
  return {
    x: cardX, y: cardTop, w: cardW, h: cardBottom - cardTop, r,
    padX, padLeft, padRight, blockShift, rtl,
  };
}

// Paint the bell note card: the dark glass card (his cardColor at
// cardOpacity — the backdrop blur is skipped, same as the music card:
// the page backgrounds are smooth gradients, so a blur would change
// almost nothing), then the bell badge overhanging the top-left corner
// and the hand-drawn line near the bottom. The text itself is painted
// per line by STYLE_PAINT.bell.
function paintBellCard(l, fs) {
  const cardC = sp('bellCardC') || '#343b40';
  const cardO = (sp('bellCardO') || 72) / 100;
  const cardBg = hexToRgba(cardC, cardO);
  const badgeBg = sp('bellBadgeC') || '#f3dcd3';
  const bellC = sp('bellC') || '#59647a';
  ctx.save();
  ctx.shadowColor = 'rgba(0, 0, 0, 0.12)';
  ctx.shadowBlur = 34;
  ctx.shadowOffsetY = 14;
  roundRect(l.x, l.y, l.w, l.h, l.r);
  ctx.fillStyle = cardBg;
  ctx.fill();
  ctx.restore();
  const badgeD = l.w * 0.248;
  const badgeX = l.x - l.w * 0.082;
  const badgeY = l.y - l.h * 0.122;
  paintBellBadge(badgeX + badgeD / 2, badgeY + badgeD / 2, badgeD, cardBg, badgeBg, bellC);
  paintBellLine(l, fs);
}

// --- Hearts tape card (Reza, 2026-11-23 — his createHeartsTapeCard
// code): a dark burgundy card with a wavy grey-blue tape strip carrying
// three pale hearts at the bottom. The strip is his SVG, drawn with
// Path2D in a 500x96 viewBox (same technique as the bell badge).
const HEARTS_STRIP = 'M 2 9 C 68 11.5, 134 5.5, 206 7.8 C 282 10, 384 7.5, 498 4.2 L 498 90 C 414 90.5, 356 93.8, 294 92.6 C 228 91.2, 166 93.2, 102 91.6 C 62 90.6, 30 89.2, 2 91.8 Z';
const HEARTS_LEFT = 'M 167 74 C 155 67, 134 54, 133 39 C 132 29, 141 24, 149 27 C 155 29, 159 35, 161 39 C 164 33, 169 26, 177 25 C 186 24, 192 31, 190 42 C 188 54, 174 66, 167 74 Z';
const HEARTS_MID = 'M 246 75 C 235 66, 218 52, 219 38 C 220 29, 228 26, 236 29 C 241 31, 244 36, 246 40 C 250 32, 256 23, 266 23 C 275 23, 279 31, 276 42 C 272 54, 255 67, 246 75 Z';
const HEARTS_RIGHT = 'M 336 75 C 323 67, 304 54, 304 39 C 304 29, 313 24, 322 27 C 328 29, 333 35, 335 39 C 338 34, 343 26, 352 25 C 361 24, 367 31, 365 42 C 363 54, 347 67, 336 75 Z';
// Draw the wavy tape strip with its three hearts at the bottom of the
// card. The strip is 83% of the card width, centred, and its bottom
// sits bottomPad above the card's bottom edge (his 6.6%).
function paintHeartsStrip(l) {
  const stripC = sp('heartsStripC') || '#a3b2c0';
  const heartC = sp('heartsHeartC') || '#f3d7ca';
  const stripW = l.w * 0.83;
  const stripH = stripW * (96 / 500);
  const stripX = l.x + (l.w - stripW) / 2;
  const stripY = l.y + l.h - l.bottomPad - stripH;
  ctx.save();
  ctx.translate(stripX, stripY);
  ctx.scale(stripW / 500, stripH / 96);
  ctx.fillStyle = stripC;
  ctx.fill(new Path2D(HEARTS_STRIP));
  ctx.fillStyle = heartC;
  ctx.fill(new Path2D(HEARTS_LEFT));
  ctx.fill(new Path2D(HEARTS_MID));
  ctx.fill(new Path2D(HEARTS_RIGHT));
  ctx.restore();
}

// Geometry of the hearts tape card around the text block (Reza,
// 2026-11-23 — his createHeartsTapeCard code). Unlike the other cards
// the text is NOT centred in the whole card: it is centred in the area
// ABOVE the strip (his flex column with space-between). So the padding
// above and below the text (P) is equal on both sides, and the strip +
// the bottom padding hang below it. The height floor grows P, so the
// text stays centred in the area above the strip. The body block's
// horizontal position follows the alignment buttons, same rule as the
// note card.
function heartsLayout(fs, maxLw, blockH, lineHeight, h, cx, rtl = true) {
  // Side padding: two knobs (2026-11-24), defaults = the old symmetric
  // padding; padX stays as their average for the symmetric chrome.
  const padLeft = Math.max(0, sp('heartsPadLeft') ?? 34);
  const padRight = Math.max(0, sp('heartsPadRight') ?? 34);
  const padX = (padLeft + padRight) / 2;
  const bodyH = blockH;
  const cardW = Math.max(maxLw + padLeft + padRight, sp('heartsCardW'));
  const cardX = cx - cardW / 2;
  const slack = Math.max(0, cardW - padLeft + padRight - maxLw) / 2;
  const blockShift = state.align === 'right' ? slack + (padLeft - padRight) / 2
    : state.align === 'left' ? -slack + (padLeft - padRight) / 2
    : state.align === 'justify' ? (rtl ? slack : -slack) + (padLeft - padRight) / 2
    : (padLeft - padRight) / 2;
  const stripW = cardW * 0.83;
  const stripH = stripW * (96 / 500);
  const bottomPad = 0.066 * sp('heartsCardH');
  const contentH = blockH + stripH + bottomPad;
  // Top/bottom space (2026-11-24): the old symmetric P was half of
  // the leftover over contentH + 2*38 — the two knobs split it, so
  // the top knob is card-top -> text-top and the bottom knob is
  // text-bottom -> strip-top; extra CardH still splits evenly.
  const padTop = Math.max(0, sp('heartsPadTop') ?? 38);
  const padBottom = Math.max(0, sp('heartsPadBottom') ?? 38);
  const cardH = Math.max(contentH + padTop + padBottom, sp('heartsCardH'));
  const extraH = cardH - contentH - padTop - padBottom;
  const topSpace = padTop + extraH / 2;
  const midSpace = padBottom + extraH / 2;
  const textTop = h / 2 - bodyH / 2;
  const textBottom = h / 2 + bodyH / 2;
  const cardTop = textTop - topSpace;
  const cardBottom = textBottom + midSpace + stripH + bottomPad;
  const r = Math.min(48, cardW * 0.06);
  return {
    x: cardX, y: cardTop, w: cardW, h: cardBottom - cardTop, r,
    padX, padLeft, padRight, blockShift, rtl, bottomPad, stripH,
  };
}

// Paint the hearts tape card: the dark burgundy card (no shadow — his
// card has none), then the wavy tape strip with its three hearts at
// the bottom. The text itself is painted per line by
// STYLE_PAINT.hearts.
function paintHeartsCard(l) {
  const cardC = sp('heartsCardC') || '#3b0b1f';
  ctx.save();
  roundRect(l.x, l.y, l.w, l.h, l.r);
  ctx.fillStyle = cardC;
  ctx.fill();
  ctx.restore();
  paintHeartsStrip(l);
}

// --- Double frame text card (Reza, 2026-11-23 — his
// createDoubleFrameTextCard code): three nested sharp-cornered
// rectangles — a white outer frame, a dark grey middle frame and a dark
// burgundy inner box — with coral pink text in the middle. One
// thickness knob (his frameThickness) drives both frames.
function doubleFrameLayout(fs, maxLw, blockH, lineHeight, h, cx, rtl = true) {
  const ft = sp('doubleFrameT') ?? 26;
  // Side padding: two knobs (2026-11-24), defaults = the old symmetric
  // padding; padX stays as their average for the symmetric chrome.
  const padLeft = Math.max(0, sp('doubleFramePadLeft') ?? 44);
  const padRight = Math.max(0, sp('doubleFramePadRight') ?? 44);
  const padX = (padLeft + padRight) / 2;
  const padTop = Math.max(0, sp('doubleFramePadTop') ?? 34), padBottom = Math.max(0, sp('doubleFramePadBottom') ?? 34);
  const bodyH = blockH;
  const cardW = Math.max(maxLw + padLeft + padRight + ft * 4, sp('doubleFrameCardW'));
  const cardX = cx - cardW / 2;
  const slack = Math.max(0, cardW - ft * 4 - padLeft + padRight - maxLw) / 2;
  const blockShift = state.align === 'right' ? slack + (padLeft - padRight) / 2
    : state.align === 'left' ? -slack + (padLeft - padRight) / 2
    : state.align === 'justify' ? (rtl ? slack : -slack) + (padLeft - padRight) / 2
    : (padLeft - padRight) / 2;
  const innerBoxH = Math.max(blockH + padTop + padBottom, 200);
  const textTop = h / 2 - bodyH / 2;
  const textBottom = h / 2 + bodyH / 2;
  let cardTop = textTop - (innerBoxH - blockH) / 2 - ft * 2;
  let cardBottom = textBottom + (innerBoxH - blockH) / 2 + ft * 2;
  // Height floor: the card is at least the set size (his card is a
  // wide, short card — the default floor is 350, not the usual 480);
  // the extra space splits evenly above and below so the text stays
  // centred.
  const extraH = Math.max(0, sp('doubleFrameCardH') - (cardBottom - cardTop));
  cardTop -= extraH / 2;
  cardBottom += extraH / 2;
  return {
    x: cardX, y: cardTop, w: cardW, h: cardBottom - cardTop, r: 0,
    padX, padLeft, padRight, ft, blockShift, rtl,
  };
}

// Paint the double frame card: three nested fillRects, all sharp
// corners (radius 0 — his design). No shadow — his card has none.
function paintDoubleFrameCard(l) {
  const outerC = sp('doubleFrameOuterC') || '#ffffff';
  const innerC = sp('doubleFrameInnerC') || '#333333';
  const bgC = sp('doubleFrameBgC') || '#2d0616';
  const ft = l.ft;
  ctx.save();
  ctx.fillStyle = outerC;
  ctx.fillRect(l.x, l.y, l.w, l.h);
  ctx.fillStyle = innerC;
  ctx.fillRect(l.x + ft, l.y + ft, l.w - 2 * ft, l.h - 2 * ft);
  ctx.fillStyle = bgC;
  ctx.fillRect(l.x + 2 * ft, l.y + 2 * ft, l.w - 4 * ft, l.h - 4 * ft);
  ctx.restore();
}

// --- Message notification card (Reza, 2026-11-23 — his
// createMessageNotificationCard code): a light-grey iOS message
// notification with two darker cards stacked behind it, peeking out
// above the front card, and a green iMessage icon + MESSAGE title +
// "now" time in the header. His backdrop is the page itself, so there
// is no blur to skip — the three flat layers ARE the look.

// His white speech-bubble path (the iMessage icon), in a 60x60
// viewBox, verbatim.
const MSGNOTIF_IMSG_BUBBLE = 'M 30 13.5 C 41.2 13.5, 50 20.1, 50 28.3 C 50 36.5, 41.2 43.1, 30 43.1 C 27.2 43.1, 24.6 42.7, 22.2 41.9 C 19.6 44.1, 16.2 45.3, 12.8 45.2 C 14.4 43.3, 15.6 41.0, 16.0 38.6 C 12.2 35.9, 10 32.3, 10 28.3 C 10 20.1, 18.8 13.5, 30 13.5 Z';

// His adjustColor helper, verbatim: the stacked layers are the card
// colour darkened by a fixed delta (-15 for the middle, -31 for the
// back layer).
function msgnotifAdjust(hex, delta) {
  const clean = hex.replace('#', '');
  if (clean.length !== 6) return hex;
  const num = parseInt(clean, 16);
  const r = Math.min(255, Math.max(0, ((num >> 16) & 255) + delta));
  const g = Math.min(255, Math.max(0, ((num >> 8) & 255) + delta));
  const b = Math.min(255, Math.max(0, (num & 255) + delta));
  return '#' + [r, g, b].map((v) => v.toString(16).padStart(2, '0')).join('');
}

// Geometry of the message notification card around the text block.
// The front card holds the header (icon + title + time) above the
// text; the two stacked layers peek out above the front card's top
// edge (back 84.5% wide, middle 93.5% — his widths). The body block's
// horizontal position follows the alignment buttons, same rule as the
// note card. The height floor grows the card evenly above and below,
// so the text stays centred on the canvas.
function msgnotifLayout(fs, maxLw, blockH, lineHeight, h, cx, rtl = true) {
  // Side padding: two knobs (2026-11-24), defaults = the old symmetric
  // padding; padX stays as their average for the symmetric chrome.
  const padLeft = Math.max(0, sp('msgnotifPadLeft') ?? 38);
  const padRight = Math.max(0, sp('msgnotifPadRight') ?? 38);
  const padX = (padLeft + padRight) / 2;
  const padTop = Math.max(0, sp('msgnotifPadTop') ?? 32), padBottom = Math.max(0, sp('msgnotifPadBottom') ?? 44);  // his max vertical padding
  const headerH = fs * 0.35;          // icon height (his max 38px)
  const bodyPadTop = 26, bodyPadBottom = 12; // his max body padding
  const topPeek = 34;                 // strips visible above the card
  const midTop = 17, backH = 80, midH = 95; // his max layer sizes
  const bodyH = blockH;
  const cardW = Math.max(maxLw + padLeft + padRight, sp('msgnotifCardW'));
  const cardX = cx - cardW / 2;
  const slack = Math.max(0, cardW - padLeft + padRight - maxLw) / 2;
  const blockShift = state.align === 'right' ? slack + (padLeft - padRight) / 2
    : state.align === 'left' ? -slack + (padLeft - padRight) / 2
    : state.align === 'justify' ? (rtl ? slack : -slack) + (padLeft - padRight) / 2
    : (padLeft - padRight) / 2;
  const textTop = h / 2 - bodyH / 2;
  const textBottom = h / 2 + bodyH / 2;
  let cardTop = textTop - bodyPadTop - headerH - padTop;
  let cardBottom = textBottom + bodyPadBottom + padBottom;
  // Height floor: the card is at least the set size; the extra space
  // splits evenly above and below so the text stays centred.
  const extraH = Math.max(0, sp('msgnotifCardH') - (cardBottom - cardTop));
  cardTop -= extraH / 2;
  cardBottom += extraH / 2;
  return {
    x: cardX, y: cardTop, w: cardW, h: cardBottom - cardTop, r: 30,
    padX, padLeft, padRight, padTop, headerH, blockShift, rtl, topPeek, midTop, backH, midH,
  };
}

// Paint the message notification card: the back layer (narrowest,
// darkest), the middle layer, then the front card with its soft
// shadow — then the header row (LTR, like the note/message chrome):
// the green iMessage icon + title on the left, the time on the right.
// The text itself is painted per line by STYLE_PAINT.msgnotif.
function paintMsgnotifCard(l, fs) {
  const cardC = sp('msgnotifCardC') || '#e3e4e6';
  const headerC = sp('msgnotifHeaderC') || '#55575b';
  const title = (sp('msgnotifTitle') || '').trim() || 'MESSAGE';
  const time = (sp('msgnotifTime') || '').trim() || 'now';
  const midC = msgnotifAdjust(cardC, -15);
  const backC = msgnotifAdjust(cardC, -31);
  ctx.save();
  // Back layer (84.5% wide) and middle layer (93.5% wide), both
  // centred; only the strips above the front card show.
  roundRect(l.x + (l.w - l.w * 0.845) / 2, l.y - l.topPeek, l.w * 0.845, l.backH, l.r);
  ctx.fillStyle = backC;
  ctx.fill();
  roundRect(l.x + (l.w - l.w * 0.935) / 2, l.y - l.topPeek + l.midTop, l.w * 0.935, l.midH, l.r);
  ctx.fillStyle = midC;
  ctx.fill();
  // Front card with his soft shadow (0 10px 26px rgba(0,0,0,0.08)).
  ctx.shadowColor = 'rgba(0, 0, 0, 0.08)';
  ctx.shadowBlur = 26;
  ctx.shadowOffsetY = 10;
  roundRect(l.x, l.y, l.w, l.h, l.r);
  ctx.fillStyle = cardC;
  ctx.fill();
  ctx.restore();
  // Header row, LTR: icon + title on the left, time on the right.
  ctx.save();
  const hy = l.y + l.padTop + l.headerH / 2;
  const iconSize = l.headerH;
  const iconX = l.x + l.padLeft, iconY = hy - iconSize / 2;
  const grad = ctx.createLinearGradient(iconX, iconY, iconX, iconY + iconSize);
  grad.addColorStop(0, '#65f67d');
  grad.addColorStop(1, '#1bc93b');
  roundRect(iconX, iconY, iconSize, iconSize, iconSize * 13.5 / 60);
  ctx.fillStyle = grad;
  ctx.fill();
  ctx.save();
  ctx.translate(iconX, iconY);
  ctx.scale(iconSize / 60, iconSize / 60);
  ctx.fillStyle = '#ffffff';
  ctx.fill(new Path2D(MSGNOTIF_IMSG_BUBBLE));
  ctx.restore();
  const headFont = `600 ${fs * 0.2}px 'Vazir', system-ui, sans-serif`;
  ctx.font = headFont;
  ctx.textBaseline = 'middle';
  ctx.fillStyle = headerC;
  if ('letterSpacing' in ctx) ctx.letterSpacing = '0.9px'; // his 0.04em
  ctx.textAlign = 'left';
  ctx.fillText(title, iconX + iconSize + fs * 0.12, hy);
  if ('letterSpacing' in ctx) ctx.letterSpacing = '0px';
  ctx.textAlign = 'right';
  ctx.fillText(time, l.x + l.w - l.padRight, hy);
  ctx.restore();
}

// --- Stitched card (Reza, 2026-11-23 — his createStitchedCard
// code): a dusty-rose card with a dashed stitch border around the
// inside edge, like sewing stitches. The dash cycle is fitted to the
// border's exact perimeter (his updateStitchFrame math, verbatim), so
// the dashes close seamlessly at the start point instead of breaking
// at a corner.

// Geometry of the stitched card around the text block. Same shape as
// the bell layout (fixed px padding, height floor splitting evenly,
// blockShift following the alignment buttons).
function stitchedLayout(fs, maxLw, blockH, lineHeight, h, cx, rtl = true) {
  // Side padding: two knobs (2026-11-24), defaults = the old symmetric
  // padding; padX stays as their average for the symmetric chrome.
  const padLeft = Math.max(0, sp('stitchedPadLeft') ?? 46);
  const padRight = Math.max(0, sp('stitchedPadRight') ?? 46);
  const padX = (padLeft + padRight) / 2;
  const padTop = Math.max(0, sp('stitchedPadTop') ?? 56), padBottom = Math.max(0, sp('stitchedPadBottom') ?? 56);  // his max vertical padding
  const bodyH = blockH;
  const cardW = Math.max(maxLw + padLeft + padRight, sp('stitchedCardW'));
  const cardX = cx - cardW / 2;
  const slack = Math.max(0, cardW - padLeft + padRight - maxLw) / 2;
  const blockShift = state.align === 'right' ? slack + (padLeft - padRight) / 2
    : state.align === 'left' ? -slack + (padLeft - padRight) / 2
    : state.align === 'justify' ? (rtl ? slack : -slack) + (padLeft - padRight) / 2
    : (padLeft - padRight) / 2;
  const textTop = h / 2 - bodyH / 2;
  const textBottom = h / 2 + bodyH / 2;
  let cardTop = textTop - padTop;
  let cardBottom = textBottom + padBottom;
  // Height floor: the card is at least the set size; the extra space
  // splits evenly above and below so the text stays centred.
  const extraH = Math.max(0, sp('stitchedCardH') - (cardBottom - cardTop));
  cardTop -= extraH / 2;
  cardBottom += extraH / 2;
  return {
    x: cardX, y: cardTop, w: cardW, h: cardBottom - cardTop, r: 36,
    padX, padLeft, padRight, blockShift, rtl,
  };
}

// Paint the stitched card: the dusty-rose card at its opacity, then
// the stitch border — a dashed rounded rect inset from the card edge.
// The dash cycle comes from his perimeter math: inset, stroke width,
// corner radius and the target cycle all scale with the card's smaller
// side, and the dash count is rounded so the pattern closes exactly.
// The text itself is painted per line by STYLE_PAINT.stitched.
function paintStitchedCard(l, fs) {
  const cardC = sp('stitchedCardC') || '#da778b';
  const cardO = (sp('stitchedCardO') || 94) / 100;
  const stitchC = sp('stitchedStitchC') || '#71333d';
  ctx.save();
  roundRect(l.x, l.y, l.w, l.h, l.r);
  ctx.fillStyle = hexToRgba(cardC, cardO);
  ctx.fill();
  ctx.restore();
  const base = Math.min(l.w, l.h);
  const inset = Math.max(14, Math.min(26, base * 0.056));
  const strokeWidth = Math.max(3.4, Math.min(5.5, base * 0.0125));
  const innerW = Math.max(10, l.w - inset * 2);
  const innerH = Math.max(10, l.h - inset * 2);
  const rx = Math.max(14, Math.min(28, base * 0.064));
  const perimeter = 2 * (innerW + innerH - 4 * rx) + 2 * Math.PI * rx;
  const targetCycle = Math.max(20, Math.min(31, base * 0.068));
  const dashCount = Math.max(12, Math.round(perimeter / targetCycle));
  const cycle = perimeter / dashCount;
  const dashLen = cycle * 0.56;
  const gapLen = cycle - dashLen;
  ctx.save();
  ctx.strokeStyle = stitchC;
  ctx.lineWidth = strokeWidth;
  ctx.lineCap = 'butt';
  ctx.setLineDash([dashLen, gapLen]);
  roundRect(l.x + inset, l.y + inset, innerW, innerH, rx);
  ctx.stroke();
  ctx.restore();
}

// --- Sewing pin card (Reza, 2026-11-23 — his createSewingPinCard
// code): an olive card with a white frame and a horizontal sewing pin
// across the top. Like the pushpin, the pin is his exact SVG rendered
// as a data-URL image (the brushstroke/pin pattern): the canvas cannot
// do his feGaussianBlur shadows or his radial head gradient, so the
// browser renders the SVG natively and the canvas draws the image —
// no external refs, so the export is never tainted.

// His mixHex helper, verbatim: blend two hex colours by a ratio
// (the head's five gradient colours all derive from the head colour).
function sewingPinMix(hexA, hexB, ratio) {
  const parse = (h) => {
    const clean = h.replace('#', '');
    const n = parseInt(clean.length === 6 ? clean : 'e34a59', 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
  };
  const [r1, g1, b1] = parse(hexA);
  const [r2, g2, b2] = parse(hexB);
  const r = Math.round(r1 + (r2 - r1) * ratio);
  const g = Math.round(g1 + (g2 - g1) * ratio);
  const b = Math.round(b1 + (b2 - b1) * ratio);
  return `rgb(${r}, ${g}, ${b})`;
}

// His sewing-pin SVG, verbatim (fixed uid 'sew-pin'). The viewBox is
// padded by 12 units on every side (-12 -12 384 100) so the blurred
// head shadow — which bleeds ~9 units above his y=0 — is not clipped
// by the image viewport; the layout compensates for the padding.
function sewingPinSvgString(headColor) {
  const uid = 'sew-pin';
  const headHighlight = sewingPinMix(headColor, '#ffd6dc', 0.45);
  const headMid = headColor;
  const headDeep = sewingPinMix(headColor, '#2e0207', 0.62);
  const headRimDark = sewingPinMix(headColor, '#0d0002', 0.88);
  const headBounce = sewingPinMix(headColor, '#ff9aa5', 0.35);
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-12 -12 384 100" width="384" height="100" style="overflow:visible">
  <defs>
    <filter id="${uid}-headShadow" x="-50%" y="-60%" width="200%" height="220%">
      <feGaussianBlur stdDeviation="5.2" />
    </filter>
    <filter id="${uid}-shaftShadow" x="-15%" y="-120%" width="130%" height="340%">
      <feGaussianBlur stdDeviation="2.6" />
    </filter>
    <linearGradient id="${uid}-metal" x1="0%" y1="0%" x2="0%" y2="100%">
      <stop offset="0%" stop-color="#1e1513" />
      <stop offset="26%" stop-color="#584742" />
      <stop offset="50%" stop-color="#b4a39a" />
      <stop offset="74%" stop-color="#503f3a" />
      <stop offset="100%" stop-color="#1b1210" />
    </linearGradient>
    <linearGradient id="${uid}-leftAO" x1="0%" y1="0%" x2="100%" y2="0%">
      <stop offset="0%" stop-color="#0e0505" stop-opacity="0.72" />
      <stop offset="16%" stop-color="#0e0505" stop-opacity="0" />
      <stop offset="86%" stop-color="#0e0505" stop-opacity="0" />
      <stop offset="100%" stop-color="#140c06" stop-opacity="0.65" />
    </linearGradient>
    <linearGradient id="${uid}-rightAO" x1="0%" y1="0%" x2="100%" y2="0%">
      <stop offset="0%" stop-color="#140c06" stop-opacity="0.65" />
      <stop offset="14%" stop-color="#0e0505" stop-opacity="0" />
      <stop offset="82%" stop-color="#0e0505" stop-opacity="0" />
      <stop offset="100%" stop-color="#221916" stop-opacity="0.5" />
    </linearGradient>
    <radialGradient id="${uid}-headGrad" cx="38%" cy="62%" r="68%" fx="34%" fy="66%">
      <stop offset="0%" stop-color="${headHighlight}" />
      <stop offset="36%" stop-color="${headMid}" />
      <stop offset="74%" stop-color="${headDeep}" />
      <stop offset="93%" stop-color="${headRimDark}" />
      <stop offset="100%" stop-color="#090001" />
    </radialGradient>
    <radialGradient id="${uid}-headSpec" cx="50%" cy="50%" r="50%">
      <stop offset="0%" stop-color="#ffffff" stop-opacity="0.58" />
      <stop offset="55%" stop-color="#ffdce2" stop-opacity="0.18" />
      <stop offset="100%" stop-color="#ffffff" stop-opacity="0" />
    </radialGradient>
    <clipPath id="${uid}-headClip">
      <circle cx="38" cy="40" r="20.5" />
    </clipPath>
  </defs>
  <ellipse cx="36" cy="25.5" rx="20" ry="18.5" fill="#2b2109" fill-opacity="0.38" filter="url(#${uid}-headShadow)" />
  <ellipse cx="37" cy="40.5" rx="19.5" ry="18" fill="#241b07" fill-opacity="0.22" filter="url(#${uid}-shaftShadow)" />
  <path d="M 54 29.5 L 160 36.2" stroke="#241b07" stroke-width="5.2" stroke-linecap="round" stroke-opacity="0.34" filter="url(#${uid}-shaftShadow)" />
  <path d="M 225 36.2 L 343 32.8" stroke="#241b07" stroke-width="4.4" stroke-linecap="round" stroke-opacity="0.28" filter="url(#${uid}-shaftShadow)" />
  <ellipse cx="161.5" cy="39.5" rx="2.6" ry="3.8" fill="#2f260c" fill-opacity="0.72" />
  <ellipse cx="224.5" cy="39.5" rx="2.6" ry="3.8" fill="#2f260c" fill-opacity="0.72" />
  <rect x="55" y="36.3" width="107.5" height="6.4" rx="3.2" fill="url(#${uid}-metal)" />
  <rect x="55" y="36.3" width="107.5" height="6.4" rx="3.2" fill="url(#${uid}-leftAO)" />
  <line x1="60" y1="39.2" x2="158" y2="39.2" stroke="#f2e6df" stroke-opacity="0.38" stroke-width="1" stroke-linecap="round" />
  <path d="M 224 36.3 L 312 36.5 L 348 39.5 L 312 42.5 L 224 42.7 A 3.2 3.2 0 0 1 224 36.3 Z" fill="url(#${uid}-metal)" />
  <path d="M 224 36.3 L 312 36.5 L 348 39.5 L 312 42.5 L 224 42.7 A 3.2 3.2 0 0 1 224 36.3 Z" fill="url(#${uid}-rightAO)" />
  <line x1="228" y1="39.2" x2="334" y2="39.4" stroke="#f2e6df" stroke-opacity="0.34" stroke-width="0.9" stroke-linecap="round" />
  <g clip-path="url(#${uid}-headClip)">
    <circle cx="38" cy="40" r="20.5" fill="url(#${uid}-headGrad)" />
    <path d="M 16 26 C 24 14, 52 14, 60 32 C 63 44, 56 58, 43 61 C 51 52, 52 36, 44 27 C 36 20, 23 22, 16 26 Z" fill="#120103" fill-opacity="0.58" />
    <ellipse cx="31.5" cy="43.5" rx="8.8" ry="6.4" transform="rotate(-24 31.5 43.5)" fill="url(#${uid}-headSpec)" />
    <path d="M 22 52 C 28 59, 41 60, 48 55" fill="none" stroke="${headBounce}" stroke-width="2" stroke-opacity="0.45" stroke-linecap="round" />
  </g>
</svg>`;
}
const sewingPinImgCache = new Map();
function getSewingPinImage(headColor) {
  const key = headColor;
  let img = sewingPinImgCache.get(key);
  if (!img) {
    img = new Image();
    img.onload = () => { redraw(); };
    img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(sewingPinSvgString(headColor));
    sewingPinImgCache.set(key, img);
  }
  return img;
}

// Geometry of the sewing pin card around the text block. Same shape
// as the stitched layout (fixed px padding, height floor splitting
// evenly, blockShift following the alignment buttons). The pin is 42%
// of the card wide, centred, its visible top 28px below the card top
// (his max top offset); the image box is offset by the 12-unit
// viewBox padding so the visible pin lands exactly there.
function sewingPinLayout(fs, maxLw, blockH, lineHeight, h, cx, rtl = true) {
  // Side padding: two knobs (2026-11-24), defaults = the old symmetric
  // padding; padX stays as their average for the symmetric chrome.
  const padLeft = Math.max(0, sp('sewingpinPadLeft') ?? 48);
  const padRight = Math.max(0, sp('sewingpinPadRight') ?? 48);
  const padX = (padLeft + padRight) / 2;
  const padTop = Math.max(0, sp('sewingpinPadTop') ?? 118), padBottom = Math.max(0, sp('sewingpinPadBottom') ?? 66); // his max vertical padding
  const bodyH = blockH;
  const cardW = Math.max(maxLw + padLeft + padRight, sp('sewingpinCardW'));
  const cardX = cx - cardW / 2;
  const slack = Math.max(0, cardW - padLeft + padRight - maxLw) / 2;
  const blockShift = state.align === 'right' ? slack + (padLeft - padRight) / 2
    : state.align === 'left' ? -slack + (padLeft - padRight) / 2
    : state.align === 'justify' ? (rtl ? slack : -slack) + (padLeft - padRight) / 2
    : (padLeft - padRight) / 2;
  const textTop = h / 2 - bodyH / 2;
  const textBottom = h / 2 + bodyH / 2;
  let cardTop = textTop - padTop;
  let cardBottom = textBottom + padBottom;
  // Height floor: the card is at least the set size; the extra space
  // splits evenly above and below so the text stays centred.
  const extraH = Math.max(0, sp('sewingpinCardH') - (cardBottom - cardTop));
  cardTop -= extraH / 2;
  cardBottom += extraH / 2;
  const pinW = cardW * 0.42;
  const pinH = pinW * 100 / 384;
  const pinX = cardX + (cardW - pinW) / 2;
  const pinY = cardTop + 28 - (12 / 100) * pinH;
  return {
    x: cardX, y: cardTop, w: cardW, h: cardBottom - cardTop, r: 28,
    padX, padLeft, padRight, blockShift, rtl, pinX, pinY, pinW, pinH,
  };
}

// Paint the sewing pin card: the olive card, then the white frame
// drawn inside the card bounds (half the stroke would spill outside
// the card edge otherwise), then the sewing pin image across the top.
// The text itself is painted per line by STYLE_PAINT.sewingpin.
function paintSewingPinCard(l, fs) {
  const cardC = sp('sewingpinCardC') || '#b2a148';
  const borderC = sp('sewingpinBorderC') || '#ffffff';
  const bw = 5; // his max border width
  ctx.save();
  roundRect(l.x, l.y, l.w, l.h, l.r);
  ctx.fillStyle = cardC;
  ctx.fill();
  ctx.restore();
  ctx.save();
  ctx.strokeStyle = borderC;
  ctx.lineWidth = bw;
  roundRect(l.x + bw / 2, l.y + bw / 2, l.w - bw, l.h - bw, Math.max(0, l.r - bw / 2));
  ctx.stroke();
  ctx.restore();
  const img = getSewingPinImage(sp('sewingpinHeadC') || '#e34a59');
  if (img.complete && img.naturalWidth > 0) {
    ctx.drawImage(img, l.pinX, l.pinY, l.pinW, l.pinH);
  }
  // (No flat fallback — the pin is too detailed to fake with paths;
  // the data: URL loads immediately and onload redraws.)
}

// --- Spiral notepad card (Reza, 2026-11-23 — his
// createSpiralNotepadCard code): an orange paper page with a black
// frame and a spiral wire binding along the top edge. The coils are
// his exact viewBox geometry (480x62, paper top edge at y=26), drawn
// with Path2D under a scale transform — each loop arches above the
// paper's top edge and dives into its punched hole below it.

// Geometry of the spiral notepad card around the text block. Same
// shape as the other card layouts (fixed px padding, blockShift
// following the alignment buttons) — with one difference: his text
// sits in the UPPER part of the page (flex-start + a deep bottom
// padding), so the height floor's extra space goes entirely BELOW
// the text instead of splitting evenly, and the text stays 96px
// below the paper top.
function spiralLayout(fs, maxLw, blockH, lineHeight, h, cx, rtl = true) {
  // Side padding: two knobs (2026-11-24), defaults = the old symmetric
  // padding; padX stays as their average for the symmetric chrome.
  const padLeft = Math.max(0, sp('spiralPadLeft') ?? 44);
  const padRight = Math.max(0, sp('spiralPadRight') ?? 44);
  const padX = (padLeft + padRight) / 2;
  const padTop = Math.max(0, sp('spiralPadTop') ?? 96), padBottom = Math.max(0, sp('spiralPadBottom') ?? 175); // his max vertical padding
  const bodyH = blockH;
  const cardW = Math.max(maxLw + padLeft + padRight, sp('spiralCardW'));
  const cardX = cx - cardW / 2;
  const slack = Math.max(0, cardW - padLeft + padRight - maxLw) / 2;
  const blockShift = state.align === 'right' ? slack + (padLeft - padRight) / 2
    : state.align === 'left' ? -slack + (padLeft - padRight) / 2
    : state.align === 'justify' ? (rtl ? slack : -slack) + (padLeft - padRight) / 2
    : (padLeft - padRight) / 2;
  const textTop = h / 2 - bodyH / 2;
  const textBottom = h / 2 + bodyH / 2;
  const cardTop = textTop - padTop;
  let cardBottom = textBottom + padBottom;
  // Height floor: the card is at least the set size; the extra space
  // goes below the text (see above), so the text stays put.
  const extraH = Math.max(0, sp('spiralCardH') - (cardBottom - cardTop));
  cardBottom += extraH;
  // How far the wire loops arch above the paper top: the loop's cubic
  // peaks at viewBox y=5.75 (its control points sit at -1, but the
  // curve only reaches 5.75), so 20.25 of the 480-wide viewBox sticks
  // out above the edge at y=26.
  const coilOverhang = (20.25 / 480) * cardW;
  return {
    x: cardX, y: cardTop, w: cardW, h: cardBottom - cardTop, r: 0,
    padX, padLeft, padRight, blockShift, rtl, coilOverhang,
  };
}

// Paint the spiral notepad card: the orange paper (sharp corners,
// radius 0 — a plain rect, like the pink frame card), the black frame
// drawn inside the paper bounds, then the spiral binding — the wire
// loops and their punched holes, in his viewBox units scaled to the
// paper width. The text itself is painted per line by
// STYLE_PAINT.spiral.
function paintSpiralCard(l, fs) {
  const paperC = sp('spiralPaperC') || '#f9ad7b';
  const wireC = sp('spiralWireC') || '#000000';
  const bw = 3.2; // his max border width
  ctx.fillStyle = paperC;
  ctx.fillRect(l.x, l.y, l.w, l.h);
  ctx.save();
  ctx.strokeStyle = wireC;
  ctx.lineWidth = bw;
  ctx.strokeRect(l.x + bw / 2, l.y + bw / 2, l.w - bw, l.h - bw);
  ctx.restore();
  const s = l.w / 480;
  const count = Math.max(2, Math.round(sp('spiralCoils') || 14));
  const startX = 18, endX = 480 - 18;
  const step = (endX - startX) / (count - 1);
  const halfW = Math.min(13, step * 0.39);
  ctx.save();
  ctx.translate(l.x, l.y - 26 * s);
  ctx.scale(s, s);
  ctx.fillStyle = wireC;
  ctx.strokeStyle = wireC;
  ctx.lineWidth = 2.7;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  for (let i = 0; i < count; i++) {
    const cx = startX + i * step;
    const leftX = cx - halfW;
    const rightX = cx + halfW;
    const holeX = cx - halfW * 0.22;
    const holeY = 52;
    ctx.beginPath();
    ctx.ellipse(holeX, holeY, 3.4, 4.1, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke(new Path2D(
      `M ${leftX.toFixed(2)} 26 C ${leftX.toFixed(2)} -1, ${rightX.toFixed(2)} -1, ${rightX.toFixed(2)} 26 ` +
      `C ${rightX.toFixed(2)} 41, ${(cx + halfW * 0.45).toFixed(2)} 52, ${holeX.toFixed(2)} 52`
    ));
  }
  ctx.restore();
}

// --- Window card (Reza, 2026-11-23 — his createWindowCard code): a
// desktop window — a terracotta title bar with the three window
// controls (minimize, maximize, close) on the right, and a white body
// with the text centred in it. The icons are his SVG paths, drawn
// with canvas strokes in their 28x28 viewBox (same technique as the
// music icons, minus the transform — the icons are a fixed 28px).

// Geometry of the window card around the text block. Same shape as
// the other card layouts (fixed px padding, height floor splitting
// evenly, blockShift following the alignment buttons). The text is
// centred in the BODY — the header sits above it — so the space above
// the text is the header height plus the body padding.
function windowLayout(fs, maxLw, blockH, lineHeight, h, cx, rtl = true) {
  // Side padding: two knobs (2026-11-24), defaults = the old symmetric
  // padding; padX stays as their average for the symmetric chrome.
  const padLeft = Math.max(0, sp('windowPadLeft') ?? 44);
  const padRight = Math.max(0, sp('windowPadRight') ?? 44);
  const padX = (padLeft + padRight) / 2;
  const headerH = 84;                 // his max header height
  const bodyPadTop = Math.max(0, sp('windowPadTop') ?? 48), bodyPadBottom = Math.max(0, sp('windowPadBottom') ?? 48); // his max body padding
  const bodyH = blockH;
  const cardW = Math.max(maxLw + padLeft + padRight, sp('windowCardW'));
  const cardX = cx - cardW / 2;
  const slack = Math.max(0, cardW - padLeft + padRight - maxLw) / 2;
  const blockShift = state.align === 'right' ? slack + (padLeft - padRight) / 2
    : state.align === 'left' ? -slack + (padLeft - padRight) / 2
    : state.align === 'justify' ? (rtl ? slack : -slack) + (padLeft - padRight) / 2
    : (padLeft - padRight) / 2;
  const textTop = h / 2 - bodyH / 2;
  const textBottom = h / 2 + bodyH / 2;
  let cardTop = textTop - headerH - bodyPadTop;
  let cardBottom = textBottom + bodyPadBottom;
  // Height floor: the card is at least the set size; the extra space
  // splits evenly above and below so the text stays centred in the
  // body.
  const extraH = Math.max(0, sp('windowCardH') - (cardBottom - cardTop));
  cardTop -= extraH / 2;
  cardBottom += extraH / 2;
  return {
    x: cardX, y: cardTop, w: cardW, h: cardBottom - cardTop, r: 28,
    padX, padLeft, padRight, headerH, blockShift, rtl,
  };
}

// Paint the window card: the rounded card clipped (overflow hidden),
// the white body filling it, the terracotta title bar across the top,
// then the three window controls — minimize, maximize, close —
// right-aligned in the LTR header, his exact viewBox coordinates at
// their fixed 28px size. His SVG icons carry no linecap, so the
// strokes use butt caps (the canvas default is butt too, but it is
// set explicitly — the shared ctx may carry 'round' from another
// style). The text itself is painted per line by
// STYLE_PAINT.windowcard.
function paintWindowCard(l, fs) {
  const headerC = sp('windowHeaderC') || '#db977d';
  const bodyC = sp('windowBodyC') || '#ffffff';
  const iconC = sp('windowIconC') || '#ffffff';
  ctx.save();
  roundRect(l.x, l.y, l.w, l.h, l.r);
  ctx.clip();
  ctx.fillStyle = bodyC;
  ctx.fillRect(l.x, l.y, l.w, l.h);
  ctx.fillStyle = headerC;
  ctx.fillRect(l.x, l.y, l.w, l.headerH);
  const iconSize = 28; // his max icon size
  const gap = 26;      // his max gap between icons
  const padRight = 32; // his max header padding
  const iconY = l.y + (l.headerH - iconSize) / 2;
  const closeX = l.x + l.w - padRight - iconSize;
  const maxX = closeX - gap - iconSize;
  const minX = maxX - gap - iconSize;
  ctx.strokeStyle = iconC;
  ctx.lineCap = 'butt';
  // Minimize: a horizontal line across the middle.
  ctx.lineWidth = 3.6;
  ctx.beginPath();
  ctx.moveTo(minX + 2, iconY + 14);
  ctx.lineTo(minX + 26, iconY + 14);
  ctx.stroke();
  // Maximize: an outlined square.
  ctx.beginPath();
  ctx.rect(maxX + 3, iconY + 3, 22, 22);
  ctx.stroke();
  // Close: an X.
  ctx.lineWidth = 3.8;
  ctx.beginPath();
  ctx.moveTo(closeX + 4, iconY + 4);
  ctx.lineTo(closeX + 24, iconY + 24);
  ctx.moveTo(closeX + 24, iconY + 4);
  ctx.lineTo(closeX + 4, iconY + 24);
  ctx.stroke();
  ctx.restore();
}

// --- Split window card (Reza, 2026-11-23 — his createSplitWindowCard
// code): a desktop window split in two — a peach title bar on top
// with three hollow black circles on the right, a gap, then a dark
// burgundy body card with the text centred in it. The circles are
// his SVG (44x44 viewBox: a circle r=18.2 centred in the box,
// stroked 3.8) drawn with canvas arcs.

// Geometry of the split window card around the text block. Same shape
// as the window card layout (fixed px padding, height floor splitting
// evenly, blockShift following the alignment buttons), but the card
// is two separate pieces: the header bar, a 12px gap, then the body
// card. The text is centred in the BODY — the extra height splits
// evenly between the top of the header and the bottom of the body, so
// the text stays centred in the body.
function splitWindowLayout(fs, maxLw, blockH, lineHeight, h, cx, rtl = true) {
  // Side padding: two knobs (2026-11-24), defaults = the old symmetric
  // padding; padX stays as their average for the symmetric chrome.
  const padLeft = Math.max(0, sp('splitWindowPadLeft') ?? 44);
  const padRight = Math.max(0, sp('splitWindowPadRight') ?? 44);
  const padX = (padLeft + padRight) / 2;
  const headerH = 74;                 // his max header height
  const headerR = 26;                 // his max header radius
  const gap = 12;                     // his max gap between header and body
  const bodyPadTop = Math.max(0, sp('splitWindowPadTop') ?? 46), bodyPadBottom = Math.max(0, sp('splitWindowPadBottom') ?? 46); // his max body padding
  const bodyR = 28;                   // his max body radius
  const bodyH = blockH;
  const cardW = Math.max(maxLw + padLeft + padRight, sp('splitWindowCardW'));
  const cardX = cx - cardW / 2;
  const slack = Math.max(0, cardW - padLeft + padRight - maxLw) / 2;
  const blockShift = state.align === 'right' ? slack + (padLeft - padRight) / 2
    : state.align === 'left' ? -slack + (padLeft - padRight) / 2
    : state.align === 'justify' ? (rtl ? slack : -slack) + (padLeft - padRight) / 2
    : (padLeft - padRight) / 2;
  const textTop = h / 2 - bodyH / 2;
  const textBottom = h / 2 + bodyH / 2;
  let bodyTop = textTop - bodyPadTop;
  let bodyBottom = textBottom + bodyPadBottom;
  let headerTop = bodyTop - gap - headerH;
  // Height floor: the card is at least the set size. The extra space
  // goes ABOVE the header and BELOW the body — the header, the gap
  // and the body top all move up together, so the gap between the two
  // cards stays exactly the set gap (12px). (Bug, Reza's screenshot
  // 2026-11-23: the extra used to push only the header up while the
  // body stayed put, so the gap ballooned to 12 + extraH/2 = 86px.)
  const extraH = Math.max(0, sp('splitWindowCardH') - (bodyBottom - headerTop));
  headerTop -= extraH / 2;
  bodyTop -= extraH / 2;
  bodyBottom += extraH / 2;
  return {
    x: cardX, y: headerTop, w: cardW, h: bodyBottom - headerTop,
    headerY: headerTop, headerH, headerR,
    bodyY: bodyTop, bodyH: bodyBottom - bodyTop, bodyR,
    padX, padLeft, padRight, gap, blockShift, rtl,
  };
}

// Paint the split window card: the peach header bar (radius 26) with
// three hollow circles on the right end, a gap, then the dark
// burgundy body card (radius 28). The text itself is painted per line
// by STYLE_PAINT.splitwindow.
function paintSplitWindowCard(l, fs) {
  const headerC = sp('splitWindowHeaderC') || '#fcb181';
  const bodyC = sp('splitWindowBodyC') || '#591f2b';
  const circleC = sp('splitWindowCircleC') || '#000000';
  // Header bar.
  ctx.fillStyle = headerC;
  roundRect(l.x, l.headerY, l.w, l.headerH, l.headerR);
  ctx.fill();
  // Body card.
  ctx.fillStyle = bodyC;
  roundRect(l.x, l.bodyY, l.w, l.bodyH, l.bodyR);
  ctx.fill();
  // Three hollow circles on the right end of the header (his SVG,
  // 44x44 viewBox: a circle r=18.2 centred in the box, stroked 3.8).
  const circleSize = 44; // his max circle size
  const gap = 13;        // his max gap between circles
  const padRight = 22;   // his max header padding
  const circleY = l.headerY + (l.headerH - circleSize) / 2;
  const c3x = l.x + l.w - padRight - circleSize;
  const c2x = c3x - gap - circleSize;
  const c1x = c2x - gap - circleSize;
  ctx.strokeStyle = circleC;
  ctx.lineWidth = 3.8;
  for (const cx of [c1x, c2x, c3x]) {
    ctx.beginPath();
    ctx.arc(cx + 22, circleY + 22, 18.2, 0, Math.PI * 2);
    ctx.stroke();
  }
}

// --- Mac window card (Reza, 2026-11-23 — his createMacWindowCard
