  // alignment buttons).
  const pinRTL = state.style === 'pin' ? isRTLText(lines[0] || '') : true;
  const pinL = state.style === 'pin' ? pinLayout(textFs, maxLw, blockH, lineHeight, h, cx, pinRTL) : null;
  // The music player card wraps the block the same way (its subtitle
