      if (item.id === 'floatshadow') return '<canvas class="sample-canvas sample-canvas-floatshadow" width="190" height="120"></canvas>';
      if (item.id === 'glowframe') return '<canvas class="sample-canvas sample-canvas-glowframe" width="190" height="120"></canvas>';
      if (item.id === 'cornerglow') return '<canvas class="sample-canvas sample-canvas-cornerglow" width="190" height="120"></canvas>';
      if (item.id === 'vibrantshadow') return '<canvas class="sample-canvas sample-canvas-vibrantshadow" width="190" height="120"></canvas>';
      if (item.id === 'glossyglass') return '<canvas class="sample-canvas sample-canvas-glossyglass" width="190" height="120"></canvas>';
      if (item.id === 'gradientshadow') return '<canvas class="sample-canvas sample-canvas-gradientshadow" width="190" height="120"></canvas>';
      if (item.id === 'fading') return '<canvas class="sample-canvas sample-canvas-fading" width="190" height="120"></canvas>';
      if (item.id === 'shinygold') return '<canvas class="sample-canvas sample-canvas-shinygold" width="190" height="120"></canvas>';
      if (item.id === 'liftedshadow') return '<canvas class="sample-canvas sample-canvas-liftedshadow" width="190" height="120"></canvas>';
      if (item.id === 'sheenribbon') return '<canvas class="sample-canvas sample-canvas-sheenribbon" width="190" height="120"></canvas>';
      if (item.id === 'emeraldgradient') return '<canvas class="sample-canvas sample-canvas-emeraldgradient" width="190" height="120"></canvas>';
      if (item.id === 'sharphighlight') return '<canvas class="sample-canvas sample-canvas-sharphighlight" width="190" height="120"></canvas>';
      if (item.id === 'glassoutline') return '<canvas class="sample-canvas sample-canvas-glassoutline" width="190" height="120"></canvas>';
      if (item.id === 'layeredgold') return '<canvas class="sample-canvas sample-canvas-layeredgold" width="190" height="120"></canvas>';
      if (item.id === 'metallicgold') return '<canvas class="sample-canvas sample-canvas-metallicgold" width="190" height="120"></canvas>';
      if (item.id === 'slantquote') return '<canvas class="sample-canvas sample-canvas-slantquote" width="190" height="120"></canvas>';
      if (item.id === 'doubleline') return '<canvas class="sample-canvas sample-canvas-doubleline" width="190" height="120"></canvas>';
      if (item.id === 'yellowbars') return '<canvas class="sample-canvas sample-canvas-yellowbars" width="190" height="120"></canvas>';
